const VERSION_BANCO = 3;

const TEMAS = [
  { id: "cielo", nombre: "Cielo y telescopios", icono: "🔭", color: "#e8475f",
    teoria: [
      { id: "constelaciones", titulo: "Constelaciones y asterismos",
        texto: "La Unión Astronómica Internacional (UAI) divide el cielo en <b>88 constelaciones</b> con límites oficiales. Hoy una constelación es una <b>región del cielo</b> con límites definidos, no solo un dibujo. Un <b>asterismo</b> es un dibujo conocido que no es una constelación oficial (por ejemplo, las Tres Marías, que forman el cinturón de <b>Orión</b>). Las estrellas de una constelación solo parecen juntas: pueden estar a distancias muy distintas de nosotros." },
      { id: "magnitud", titulo: "Brillo: la escala de magnitudes",
        texto: "El brillo aparente se mide en <b>magnitudes</b>: cuanto <b>menor</b> el número, <b>más brillante</b> el astro. Una diferencia de 5 magnitudes es un factor 100 en brillo, y cada magnitud es un factor de unas <b>2,512</b> veces: la razón de brillos es 2,512<sup>Δm</sup> (2 magnitudes ≈ 6,3 veces). A simple vista, con cielo oscuro, se ven estrellas hasta magnitud <b>6</b>. Sirio, la estrella más brillante de la noche, tiene magnitud −1,5; Venus llega a −4,6 y es el astro más brillante después del Sol y la Luna. Algunas estrellas brillantes del cielo austral: Canopus (−0,7), Arturo (−0,1), Rigel (0,1), Achernar (0,5) y Acrux (0,9)." },
      { id: "planetas", titulo: "Planetas a simple vista",
        texto: "Mercurio, Venus, Marte, Júpiter y Saturno se ven a simple vista. Se distinguen de las estrellas porque <b>cambian de posición</b> entre ellas con el paso de los días (planeta = «errante»), suelen titilar menos y siempre están cerca de la eclíptica. <b>Urano</b> y Neptuno no se consideran visibles a simple vista (Urano está justo en el límite, magnitud 5,7). Mercurio y Venus son <b>planetas interiores</b>: nunca se alejan mucho del Sol en el cielo, por eso solo se ven al amanecer o al atardecer, nunca a medianoche." },
      { id: "telescopios", titulo: "Telescopios",
        texto: "La función principal de un telescopio es <b>captar más luz</b> que el ojo: lo más importante es el <b>diámetro (apertura)</b> del objetivo, que también mejora la resolución. El <b>refractor</b> usa una lente como objetivo y el <b>reflector</b> un espejo. El aumento es <b>A = f<sub>objetivo</sub> / f<sub>ocular</sub></b>. El <b>poder separador</b> (resolución) es el menor ángulo entre dos estrellas que el telescopio puede mostrar separadas: un sistema doble más cerrado que ese no se resuelve. Las lentes producen <b>aberración cromática</b> (bordes de colores), por eso los reflectores no la tienen. La <b>montura</b> sostiene el tubo y puede llevar un motor para seguir a los astros. <b>Nunca</b> se mira el Sol sin un filtro solar adecuado: causa daño permanente en la vista." },
      { id: "objetos", titulo: "Vía Láctea y objetos de cielo profundo",
        texto: "La <b>Vía Láctea</b> se ve como una franja porque estamos dentro del disco de nuestra galaxia y lo vemos de canto. Desde el hemisferio sur se ven a simple vista las <b>Nubes de Magallanes</b>, dos galaxias satélites de la Vía Láctea. También hay cúmulos de estrellas (como las Pléyades) y nebulosas (como la de Orión)." }
    ] },
  { id: "diurno", nombre: "Movimiento diurno", icono: "🌐", color: "#f28c28",
    teoria: [
      { id: "rotacion", titulo: "Por qué gira el cielo",
        texto: "La Tierra rota de <b>oeste a este</b>; por eso todo el cielo parece girar de <b>este a oeste</b> alrededor del <b>eje del mundo</b>, que pasa por los polos celestes. Los astros salen por el lado este, culminan al cruzar el meridiano y se ponen por el lado oeste. Desde el hemisferio sur, mirando al sur, las estrellas giran alrededor del polo sur celeste en <b>sentido horario</b>. Todos los astros describen círculos <b>paralelos al ecuador celeste</b> y todos giran con la <b>misma velocidad angular</b>: <b>15° por hora</b> (360° en un día). Una foto de larga exposición de 2 horas muestra arcos de 30° alrededor del polo." },
      { id: "esfera", titulo: "La esfera celeste",
        texto: "El <b>cenit</b> es el punto justo sobre nuestra cabeza y el <b>nadir</b> el opuesto. El <b>horizonte</b> separa la mitad visible del cielo. El <b>meridiano</b> del lugar pasa por los polos celestes, el cenit y los puntos cardinales norte y sur. El <b>ecuador celeste</b> corta el horizonte en los puntos <b>este y oeste</b>. Cuando un astro cruza el meridiano alcanza su altura máxima (<b>culminación</b>). La <b>altura del polo celeste</b> sobre el horizonte es igual a la <b>latitud</b> del lugar." },
      { id: "circumpolares", titulo: "Estrellas circumpolares",
        texto: "En Montevideo (latitud ≈ 35° S) el polo sur celeste está a unos <b>35°</b> sobre el horizonte sur. Las estrellas a menos de 35° de ese polo <b>nunca se ponen</b>: son <b>circumpolares</b>. Las cercanas al polo norte celeste <b>nunca salen</b>: por eso desde Uruguay no se ve la estrella Polar. Las estrellas cercanas al <b>ecuador celeste</b> (como las de Orión) no son circumpolares en ningún lugar del planeta. Una circumpolar culmina dos veces: arriba del polo a una altura <b>φ + p</b> y debajo a <b>φ − p</b>, donde φ es la latitud y p la distancia de la estrella al polo." },
      { id: "latitud", titulo: "El cielo según la latitud",
        texto: "En un <b>polo</b> terrestre, el polo celeste está en el cenit y las estrellas giran en círculos <b>paralelos al horizonte</b>: ninguna sale ni se pone. En el <b>ecuador</b>, los polos celestes están sobre el horizonte y todas las estrellas salen y se ponen perpendicularmente a él; a lo largo del año se puede ver todo el cielo." },
      { id: "sidereo", titulo: "Día sidéreo y día solar",
        texto: "La Tierra da una vuelta respecto a las estrellas en <b>23 h 56 min</b> (día sidéreo), unos 4 minutos menos que el día solar de 24 h, porque mientras rota también avanza en su órbita. Por eso cada estrella sale <b>unos 4 minutos antes</b> cada día (unas 2 horas por mes) y las constelaciones visibles cambian a lo largo del año. Desde Uruguay, al anochecer, el <b>Escorpión</b> está alto en <b>invierno</b> y <b>Orión</b> en verano. En junio el Sol está cerca de Sirio en el cielo, así que al atardecer Sirio se ve bajo hacia el <b>oeste</b>." }
    ] },
  { id: "orientacion", nombre: "Orientación", icono: "🧭", color: "#f2c230",
    teoria: [
      { id: "sol", titulo: "Orientarse con el Sol",
        texto: "El Sol sale <b>exactamente por el este</b> y se pone por el oeste solo en los <b>equinoccios</b>. En verano austral sale por el <b>sudeste</b> y en invierno por el <b>noreste</b>. En Uruguay, al <b>mediodía solar</b> el Sol siempre está hacia el <b>norte</b>, por eso las sombras apuntan al <b>sur</b>. Si miras al norte, el este queda a tu derecha." },
      { id: "gnomon", titulo: "El gnomon",
        texto: "Un <b>gnomon</b> es un palo vertical. Su sombra es <b>más corta al mediodía solar</b> y en ese momento marca la línea <b>norte–sur</b> (la meridiana). Otro método: marcar la punta de la sombra a la mañana y a la tarde cuando tiene la <b>misma longitud</b>; la línea que une esas marcas va de <b>este a oeste</b> y su perpendicular indica el norte–sur." },
      { id: "cruz", titulo: "La Cruz del Sur",
        texto: "La <b>Cruz del Sur</b> se reconoce junto a sus dos <b>punteros</b>, Alfa y Beta Centauri. Para hallar el <b>polo sur celeste</b> se prolonga el <b>eje mayor</b> de la Cruz, que va de <b>Gacrux</b> (la cabeza) a <b>Acrux</b> (el pie), unas <b>4,5 veces</b> su longitud. Otro método: el polo está aproximadamente en el <b>punto medio entre Acrux y Achernar</b>. Desde ese punto se baja verticalmente al horizonte y allí está el <b>punto cardinal sur</b>. En el hemisferio norte, la estrella <b>Polar</b> marca aproximadamente el norte." },
      { id: "brujula", titulo: "La brújula",
        texto: "La brújula apunta al <b>norte magnético</b>, que no coincide exactamente con el norte geográfico. La diferencia entre ambos se llama <b>declinación magnética</b> y depende del lugar y de la época. El <b>acimut</b> indica la dirección sobre el horizonte; en astronomía suele medirse desde el sur hacia el oeste (S = 0°, O = 90°, N = 180°, E = 270°)." }
    ] },
  { id: "distancias", nombre: "UA y año luz", icono: "📏", color: "#4fbf5b",
    teoria: [
      { id: "ua", titulo: "Unidad astronómica (UA)",
        texto: "La <b>unidad astronómica</b> es la distancia media Tierra–Sol: <b>1 UA ≈ 150 millones de km</b>. Sirve para el Sistema Solar: Marte está a 1,5 UA del Sol, Júpiter a 5,2 UA, Saturno a 9,5 UA y Neptuno a unas 30 UA." },
      { id: "al", titulo: "Año luz (AL)",
        texto: "El <b>año luz</b> es una unidad de <b>distancia</b> (¡no de tiempo!): lo que recorre la luz en un año, a unos 300 000 km/s. <b>1 AL ≈ 9,5 billones de km</b> (9,5 × 10¹² km) ≈ <b>63 000 UA</b>. Se usa para estrellas y galaxias: Próxima Centauri, la estrella más cercana después del Sol, está a 4,2 AL; la Vía Láctea mide unos 100 000 AL y la galaxia de Andrómeda está a unos 2,5 millones de AL." },
      { id: "tiempo", titulo: "Mirar lejos es mirar al pasado",
        texto: "La luz tarda en llegar: desde la Luna, unos <b>1,3 segundos</b>; desde el Sol, unos <b>8 minutos</b> (1 UA ÷ velocidad de la luz ≈ 500 s); hasta Neptuno, unas 4 horas. Si una estrella está a 100 AL, la luz que vemos hoy salió de ella <b>hace 100 años</b>." }
    ] },
  { id: "estaciones", nombre: "Estaciones y Sol", icono: "☀️", color: "#ff7a3d",
    teoria: [
      { id: "causa", titulo: "La causa de las estaciones",
        texto: "Las estaciones se deben a la <b>inclinación del eje de la Tierra</b>, de unos <b>23,4°</b> respecto a la perpendicular al plano de su órbita. A lo largo del año cada hemisferio recibe la luz del Sol más o menos de frente y por más o menos horas. <b>No</b> se deben a la distancia al Sol: la Tierra está más cerca (perihelio) a principios de <b>enero</b>, cuando en el sur es verano y en el norte invierno. Las estaciones son opuestas en cada hemisferio." },
      { id: "fechas", titulo: "Solsticios y equinoccios",
        texto: "En el hemisferio sur: <b>solsticio de verano ≈ 21 de diciembre</b> (día más largo), <b>solsticio de invierno ≈ 21 de junio</b> (día más corto), equinoccios ≈ 20 de marzo (otoño) y ≈ 22 de setiembre (primavera). En los <b>equinoccios</b> el día y la noche duran casi lo mismo en todo el planeta. En el solsticio de junio, en el polo sur es de noche las 24 horas." },
      { id: "ecliptica", titulo: "La eclíptica",
        texto: "La <b>eclíptica</b> es el camino aparente que recorre el Sol entre las estrellas a lo largo del año, avanzando cerca de <b>1° por día</b> y pasando por las constelaciones del zodíaco. Corta al ecuador celeste en dos puntos, <b>Aries y Libra</b> (los equinoccios): la recta que los une es la intersección de los planos del ecuador celeste y la eclíptica." },
      { id: "altura", titulo: "Altura del Sol al mediodía",
        texto: "En Montevideo (35° S) la altura del Sol al mediodía es de unos <b>55°</b> en los equinoccios (90° − 35°), unos <b>78°</b> en el solsticio de verano (55° + 23,4°) y unos <b>31°</b> en el de invierno (55° − 23,4°). El Sol solo pasa por el <b>cenit</b> entre los trópicos: el <b>Trópico de Capricornio</b> (23,4° S) es la latitud más austral donde ocurre, el 21 de diciembre. Montevideo está más al sur, así que aquí nunca pasa por el cenit. Al revés, si sabemos la altura del Sol al mediodía en un equinoccio, la latitud es 90° menos esa altura. En el solsticio de junio (de Cáncer) el Sol sale desplazado hacia el <b>noreste</b> y tiene su <b>menor</b> altura de culminación del año." }
    ] },
  { id: "luna", nombre: "Fases de la Luna", icono: "🌙", color: "#3fa7d6",
    teoria: [
      { id: "causa", titulo: "Por qué hay fases",
        texto: "La Luna no tiene luz propia: siempre tiene una mitad iluminada por el Sol. Según la posición Sol–Tierra–Luna, desde la Tierra vemos <b>una parte distinta de esa mitad iluminada</b>. Las fases <b>no</b> son la sombra de la Tierra (eso es un eclipse). En <b>Luna nueva</b> la Luna está aproximadamente en la dirección del Sol; en <b>Luna llena</b>, en la dirección opuesta; en los <b>cuartos</b>, a 90°." },
      { id: "ciclo", titulo: "El ciclo de fases",
        texto: "Orden: nueva → creciente → <b>cuarto creciente</b> → gibosa creciente → llena → gibosa menguante → <b>cuarto menguante</b> → menguante → nueva. El ciclo completo (<b>mes sinódico</b>) dura <b>29,5 días</b>; entre una fase principal y la siguiente pasa más o menos una semana. La vuelta respecto a las estrellas (mes sidéreo) dura 27,3 días." },
      { id: "horarios", titulo: "Cuándo se ve cada fase",
        texto: "<b>Luna nueva</b>: sale y se pone con el Sol, no se ve. <b>Cuarto creciente</b>: sale cerca del mediodía, está alta al atardecer y se pone a medianoche (se ve de tarde y en la primera mitad de la noche). <b>Luna llena</b>: sale al ponerse el Sol, culmina a <b>medianoche</b> y se ve toda la noche. <b>Cuarto menguante</b>: sale a medianoche y se ve de madrugada y de mañana. Cada día la Luna sale unos <b>50 minutos más tarde</b>. Por eso puede verse de día en muchas fases." },
      { id: "forma", titulo: "La forma según el hemisferio",
        texto: "En el hemisferio sur la Luna creciente tiene el lado iluminado hacia la izquierda: se parece a una <b>C</b>; la menguante se parece a una D. En el hemisferio norte es al revés (allá dicen que la Luna es «mentirosa»)." },
      { id: "cara", titulo: "Siempre la misma cara",
        texto: "La Luna tarda lo mismo en girar sobre sí misma que en dar una vuelta a la Tierra (<b>rotación sincrónica</b>), por eso siempre nos muestra la misma cara. La «cara oculta» recibe luz del Sol igual que la visible: no es un «lado oscuro»." }
    ] },
  { id: "eclipses", nombre: "Eclipses", icono: "🌑", color: "#8e5bd6",
    teoria: [
      { id: "tipos", titulo: "Eclipse de Sol y de Luna",
        texto: "En un <b>eclipse de Sol</b> la Luna se interpone entre el Sol y la Tierra: solo puede ocurrir en <b>Luna nueva</b>. En un <b>eclipse de Luna</b> la Tierra se interpone entre el Sol y la Luna, y la sombra de la Tierra cae sobre la Luna: solo puede ocurrir en <b>Luna llena</b>." },
      { id: "nodos", titulo: "Por qué no hay eclipses todos los meses",
        texto: "La órbita de la Luna está <b>inclinada unos 5°</b> respecto a la eclíptica. Casi siempre la Luna nueva pasa por encima o por debajo del Sol, y la Luna llena por encima o por debajo de la sombra terrestre. Solo hay eclipses cuando la Luna está cerca de los <b>nodos</b> (cruces con la eclíptica), en «temporadas de eclipses» cada unos 6 meses. Cada año hay <b>al menos 2 eclipses de Sol</b> (aunque sean parciales). El <b>ciclo de Saros</b> (18 años y 11 días) repite eclipses parecidos." },
      { id: "solar", titulo: "Eclipses de Sol: total, parcial, anular",
        texto: "El Sol es unas 400 veces más grande que la Luna pero está unas <b>400 veces más lejos</b>, así que ambos se ven casi del mismo tamaño: por eso son posibles los eclipses totales. Desde la <b>umbra</b> (sombra total), en una <b>franja angosta</b>, el eclipse es total: dura como mucho unos <b>7 minutos</b> y se ve la <b>corona solar</b>. Desde la penumbra se ve parcial. Si la Luna está cerca de su punto más lejano (<b>apogeo</b>) se ve más chica que el Sol y el eclipse es <b>anular</b>." },
      { id: "lunar", titulo: "Eclipses de Luna",
        texto: "Un eclipse de Luna se ve desde <b>toda la mitad de la Tierra donde es de noche</b>. En la totalidad la Luna se ve <b>rojiza</b>: la atmósfera terrestre desvía (refracta) la luz del Sol hacia la sombra y filtra el azul, dejando pasar sobre todo el rojo. Mirarlo no tiene ningún peligro." },
      { id: "seguridad", titulo: "Observar un eclipse de Sol sin riesgo",
        texto: "Nunca mires el Sol directamente, ni siquiera parcialmente eclipsado. Usa <b>filtros certificados</b> para observación solar o el método de <b>proyección</b>. Lentes de sol, vidrios ahumados o radiografías <b>no protegen</b>." }
    ] },
  { id: "calendario", nombre: "Calendario", icono: "📅", color: "#d6457f",
    teoria: [
      { id: "unidades", titulo: "Día, mes y año",
        texto: "El calendario se basa en ciclos astronómicos: el <b>día solar</b> (tiempo entre dos pasos del Sol por el meridiano), el <b>mes</b> (ciclo de fases lunares, 29,5 días) y el <b>año trópico</b> (ciclo de las estaciones), que dura <b>365,2422 días</b>: unas 6 horas más que 365 días. La semana de 7 días viene de los 7 astros que se mueven entre las estrellas: Sol, Luna, Marte (martes), Mercurio (miércoles), Júpiter (jueves), Venus (viernes) y Saturno." },
      { id: "juliano", titulo: "Calendario juliano",
        texto: "Lo impuso Julio César en el 46 a. C.: <b>un año bisiesto cada 4 años, sin excepciones</b>, con un año medio de 365,25 días. Como es algo más largo que el año trópico, se atrasa 1 día cada unos 128 años: en el siglo XVI el equinoccio ya caía unos 10 días antes de su fecha." },
      { id: "gregoriano", titulo: "Calendario gregoriano",
        texto: "En 1582 el papa Gregorio XIII corrigió el desfase: al <b>jueves 4 de octubre</b> le siguió el <b>viernes 15 de octubre</b>. Desde entonces los años <b>seculares</b> (terminados en 00) solo son bisiestos si son <b>divisibles por 400</b>: 1900 no fue bisiesto, 2000 sí, 2100 no lo será, 2400 sí. El año medio queda en 365,2425 días." },
      { id: "lunares", titulo: "Calendarios lunares y la Pascua",
        texto: "El calendario <b>islámico</b> es lunar: 12 meses lunares, unos 354 días, por eso sus fiestas van cambiando de estación. Los calendarios hebreo y chino son <b>lunisolares</b>. La <b>Pascua</b> (y con ella la Semana de Turismo) cae el primer domingo después de la primera Luna llena posterior al equinoccio de marzo." },
      { id: "hora", titulo: "Hora solar y hora oficial",
        texto: "La Tierra gira 15° por hora, por eso cada <b>huso horario</b> abarca <b>15° de longitud</b>. Uruguay usa UTC−3, la hora del meridiano 45° O, pero Montevideo está a unos 56° O: unos 11° más al oeste, o sea 11 × 4 min ≈ 45 min. Por eso el <b>mediodía solar</b> en Montevideo ocurre cerca de las <b>12:45</b> de la hora oficial (varía unos minutos durante el año)." }
    ] },
  { id: "sistema", nombre: "Sistema Solar", icono: "🪐", color: "#2bb3a0",
    teoria: [
      { id: "estructura", titulo: "Estructura",
        texto: "El Sol concentra el <b>99,8 %</b> de la masa del Sistema Solar. Hay <b>8 planetas</b>: los rocosos (Mercurio, Venus, Tierra, Marte) y los gigantes (Júpiter y Saturno, gaseosos; Urano y Neptuno, helados). El <b>cinturón de asteroides</b> está entre Marte y Júpiter (ordenados desde el Sol: planetas rocosos, cinturón de asteroides, planetas gigantes, cinturón de Kuiper); más allá de Neptuno está el cinturón de Kuiper y, mucho más lejos, la nube de Oort, de donde vienen muchos cometas." },
      { id: "planeta", titulo: "¿Qué es un planeta?",
        texto: "Según la UAI (2006), un planeta gira alrededor del Sol, tiene masa suficiente para ser casi esférico y <b>ha limpiado su órbita</b> de otros cuerpos. <b>Plutón</b> no cumple lo último: es un <b>planeta enano</b>, como Ceres y Eris." },
      { id: "datos", titulo: "Datos de los planetas",
        texto: "<b>Júpiter</b> es el más grande. <b>Mercurio</b> es el más cercano al Sol y el más chico. <b>Venus</b> es el más caliente (unos 465 °C) por el efecto invernadero de su atmósfera de CO₂. <b>Marte</b> es rojizo por el óxido de hierro de su superficie. <b>Los cuatro gigantes tienen anillos</b>, aunque los de Saturno son los más vistosos. <b>Urano</b> tiene el eje tan inclinado (~98°) que «rueda» sobre su órbita. Neptuno es el más lejano. <b>Saturno</b> es el planeta con más lunas conocidas, seguido por Júpiter. De las lunas galileanas de Júpiter, <b>Ío</b> es el cuerpo con más actividad volcánica del Sistema Solar, Ganímedes es la luna más grande del Sistema Solar y Europa tiene un océano bajo su hielo." },
      { id: "kepler", titulo: "Leyes de Kepler",
        texto: "1) Las órbitas son <b>elipses</b> con el Sol en un foco. 2) La línea Sol–planeta barre áreas iguales en tiempos iguales: el planeta va <b>más rápido cerca del Sol</b> (perihelio). 3) T² ∝ a³: cuanto <b>más lejos</b> está un planeta, <b>más tarda</b> en dar la vuelta al Sol." },
      { id: "menores", titulo: "Cometas y meteoros",
        texto: "Un <b>cometa</b> es un núcleo de hielo y polvo; al acercarse al Sol forma una coma y colas que apuntan en <b>dirección opuesta al Sol</b>, empujadas por la radiación y el viento solar. Una «estrella fugaz» es un <b>meteoro</b>: una partícula que se quema al entrar en la atmósfera. El cuerpo que viaja por el espacio antes de entrar es un <b>meteoroide</b>. Si un fragmento llega al suelo, es un <b>meteorito</b>. Las lluvias de meteoros ocurren cuando la Tierra cruza restos que dejó un cometa." },
      { id: "origen", titulo: "Origen y evolución",
        texto: "El Sistema Solar se formó hace unos <b>4600 millones de años</b> a partir del colapso de una nube de gas y polvo, que formó un disco alrededor del Sol joven. Cerca del Sol hacía demasiado calor para que se condensaran hielos y solo quedaron <b>rocas y metales</b>: así se formaron los planetas rocosos. Más lejos, con hielo y mucho gas, crecieron los gigantes. El Sol brilla por <b>fusión nuclear</b> de hidrógeno en helio en su núcleo; dentro de unos 5000 millones de años será una gigante roja y luego una enana blanca." }
    ] }
];

const PREGUNTAS = [];
const esDePrueba = p => p.fuente.startsWith("OUA"); // preguntas tomadas de pruebas reales de la OUA
function q(tema, p, ops, exp, ref, fuente) {
  PREGUNTAS.push({ id: tema + "-" + (PREGUNTAS.filter(x => x.tema === tema).length + 1), tema, p, ops, exp, ref, fuente: fuente || "" });
}

// ───────── Cielo a simple vista y con telescopios ─────────
q("cielo", "¿Cuántas constelaciones reconoce oficialmente la Unión Astronómica Internacional?", ["88", "12", "48", "110"], "Son 88, con límites oficiales. 12 son las del zodíaco y 48 las que listó Ptolomeo.", "constelaciones");
q("cielo", "Una estrella de magnitud 1 comparada con una de magnitud 3:", ["Se ve más brillante", "Se ve menos brillante", "Está necesariamente más cerca", "Es necesariamente más grande"], "En la escala de magnitudes, un número menor indica un astro más brillante. El brillo aparente no dice por sí solo la distancia ni el tamaño.", "magnitud");
q("cielo", "Con un cielo bien oscuro, ¿hasta qué magnitud se pueden ver estrellas a simple vista?", ["Hasta magnitud 6 aproximadamente", "Hasta magnitud 0", "Hasta magnitud 15", "Hasta magnitud −4"], "El ojo humano llega a magnitud 6 en un cielo oscuro. Para ver estrellas más débiles hace falta un instrumento.", "magnitud");
q("cielo", "¿Qué característica de un telescopio es la más importante para ver objetos débiles?", ["El diámetro de su objetivo (apertura)", "El largo del tubo", "El aumento del ocular", "El color del tubo"], "Un objetivo más grande capta más luz y además da mejor resolución. El aumento solo agranda la imagen.", "telescopios");
q("cielo", "En un telescopio reflector, el objetivo es:", ["Un espejo", "Una lente", "Un prisma", "Un filtro"], "El reflector concentra la luz con un espejo; el refractor lo hace con una lente.", "telescopios");
q("cielo", "Las Nubes de Magallanes, visibles desde Uruguay, son:", ["Galaxias satélites de la Vía Láctea", "Nebulosas dentro del Sistema Solar", "Nubes muy altas de la atmósfera", "Cúmulos de estrellas de Orión"], "Son dos galaxias pequeñas que orbitan la nuestra, visibles a simple vista desde el hemisferio sur.", "objetos");
q("cielo", "¿Cómo se puede distinguir a simple vista un planeta de una estrella?", ["El planeta cambia de posición entre las estrellas con el paso de los días", "El planeta titila mucho más que las estrellas", "Los planetas solo se ven de día", "Los planetas siempre están en el cenit"], "«Planeta» significa errante: se desplaza entre las estrellas. Además suele titilar menos, no más.", "planetas");
q("cielo", "Las «Tres Marías» forman parte de la constelación de:", ["Orión", "Escorpio", "Cruz del Sur", "Centauro"], "Son el cinturón de Orión, un asterismo dentro de esa constelación.", "constelaciones");
q("cielo", "Las estrellas que forman una misma constelación:", ["Pueden estar a distancias muy distintas de nosotros", "Están todas a la misma distancia", "Giran unas alrededor de otras", "Están dentro del Sistema Solar"], "Solo parecen juntas vistas desde la Tierra; en general no tienen relación física entre sí.", "constelaciones");
q("cielo", "¿Cuál es el astro más brillante del cielo nocturno después de la Luna?", ["Venus", "Sirio", "Júpiter", "La estrella Polar"], "Venus llega a magnitud −4,6; Sirio, la estrella más brillante, tiene −1,5.", "magnitud");
q("cielo", "¿Por qué Venus nunca se ve a medianoche desde Uruguay?", ["Porque es un planeta interior y nunca se aleja mucho del Sol en el cielo", "Porque siempre está detrás de la Luna", "Porque solo es visible en invierno", "Porque su luz es demasiado débil"], "Venus y Mercurio orbitan más cerca del Sol que la Tierra: solo se ven poco antes del amanecer o después del atardecer.", "planetas");
q("cielo", "¿Qué NUNCA se debe mirar con un telescopio sin un filtro adecuado?", ["El Sol", "La Luna llena", "Júpiter", "Una nebulosa"], "La luz del Sol concentrada por el telescopio daña la vista de forma permanente en un instante.", "telescopios");
q("cielo", "¿Por qué la Vía Láctea se ve como una franja en el cielo?", ["Porque vemos de canto el disco de nuestra galaxia, desde adentro", "Porque es una nube de la atmósfera", "Porque es la cola de un cometa", "Porque marca la órbita de la Luna"], "Nuestra galaxia es un disco y el Sol está dentro de él: en la dirección del disco vemos muchísimas estrellas.", "objetos");
q("cielo", "¿Cuál es la estrella más brillante del cielo nocturno?", ["Sirio", "La estrella Polar", "Antares", "Betelgeuse"], "Sirio, en el Can Mayor, tiene magnitud −1,5. La Polar es bastante modesta (magnitud 2).", "magnitud");

// ───────── Movimiento diurno general ─────────
q("diurno", "Desde Uruguay, mirando hacia el sur de noche, las estrellas parecen girar alrededor del polo sur celeste:", ["En sentido horario", "En sentido antihorario", "No giran", "Unas en cada sentido"], "Las estrellas salen por el este (a tu izquierda) y se ponen por el oeste (a tu derecha): sobre el polo se mueven de izquierda a derecha, en sentido horario.", "rotacion");
q("diurno", "En Montevideo (latitud ≈ 35° S), el polo sur celeste está a una altura aproximada de:", ["35°", "55°", "0°", "90°"], "La altura del polo es igual a la latitud: unos 35° sobre el horizonte sur.", "circumpolares");
q("diurno", "Una estrella circumpolar es aquella que, vista desde un lugar dado:", ["Nunca se pone", "Está justo en el polo", "Solo se ve desde los polos", "Gira alrededor del Sol"], "Está tan cerca del polo celeste visible que su círculo diario queda todo sobre el horizonte.", "circumpolares");
q("diurno", "Para un observador en el polo sur, las estrellas:", ["Giran en círculos paralelos al horizonte y ninguna sale ni se pone", "Salen verticalmente por el este", "Pasan todas por el cenit", "No se mueven"], "Con el polo celeste en el cenit, el ecuador celeste coincide con el horizonte.", "latitud");
q("diurno", "Para un observador en el ecuador terrestre:", ["Todas las estrellas salen y se ponen, y los polos celestes están en el horizonte", "Ninguna estrella se pone", "Solo se ven estrellas del hemisferio norte", "El polo sur celeste está en el cenit"], "Con latitud 0°, la altura del polo celeste es 0°: los dos polos quedan sobre el horizonte.", "latitud");
q("diurno", "¿Cuánto dura un día sidéreo (una vuelta de la Tierra respecto a las estrellas)?", ["23 h 56 min", "24 h exactas", "24 h 4 min", "12 h"], "Unos 4 minutos menos que el día solar, porque la Tierra también avanza en su órbita.", "sidereo");
q("diurno", "El punto de la esfera celeste que está exactamente sobre la cabeza del observador se llama:", ["Cenit", "Nadir", "Polo celeste", "Punto Aries"], "El cenit está arriba; el nadir es el punto opuesto, bajo nuestros pies.", "esfera");
q("diurno", "El meridiano del lugar es el círculo de la esfera celeste que pasa por:", ["Los polos celestes, el cenit y los puntos cardinales norte y sur", "Los puntos este y oeste y el cenit", "El Sol y la Luna", "Los puntos Aries y Libra"], "Divide el cielo en una mitad este y una mitad oeste.", "esfera");
q("diurno", "¿Por qué la estrella Polar no se puede ver desde Montevideo?", ["Porque está cerca del polo norte celeste, que queda unos 35° bajo nuestro horizonte", "Porque es muy débil", "Porque solo se ve en verano", "Porque la tapa la Cruz del Sur"], "Las estrellas cercanas al polo norte celeste nunca salen para un observador del hemisferio sur.", "circumpolares");
q("diurno", "Cuando un astro cruza el meridiano del lugar:", ["Alcanza su máxima altura (culmina)", "Sale por el horizonte", "Se pone", "Pasa siempre por el cenit"], "Esa es la culminación; solo los astros con la declinación adecuada pasan por el cenit.", "esfera");
q("diurno", "El ecuador celeste corta al horizonte en los puntos cardinales:", ["Este y oeste", "Norte y sur", "Cenit y nadir", "Depende de la estación"], "Por eso un astro sobre el ecuador celeste (como el Sol en los equinoccios) sale exactamente por el este.", "esfera");

