// ───────── Fases de la Luna ─────────
q("luna", "Las fases de la Luna se producen porque:", ["Desde la Tierra vemos una parte distinta de su mitad iluminada por el Sol", "La sombra de la Tierra tapa parte de la Luna", "Las nubes tapan parte de la Luna", "La Luna cambia su brillo propio"], "La Luna siempre tiene una mitad iluminada; cambia cuánto de esa mitad vemos. La sombra de la Tierra solo interviene en los eclipses.", "causa");
q("luna", "La Luna llena sale aproximadamente:", ["Cuando se pone el Sol", "Al mediodía", "A medianoche", "Al amanecer"], "Está en dirección opuesta al Sol: sale cuando él se pone y se ve toda la noche.", "horarios");
q("luna", "La Luna en cuarto menguante se ve principalmente:", ["De madrugada y de mañana", "Al atardecer", "Toda la noche", "Nunca"], "Sale cerca de medianoche y sigue en el cielo de mañana.", "horarios");
q("luna", "En Luna nueva, la Luna está:", ["Aproximadamente en la misma dirección que el Sol", "Del otro lado de la Tierra respecto al Sol", "A 90° del Sol", "Detrás del Sol"], "Su cara iluminada mira al Sol y nos muestra la cara oscura; además está perdida en el brillo del día.", "causa");
q("luna", "Vista desde el hemisferio sur, la Luna creciente se parece a la letra:", ["C", "D", "O", "No se ve"], "En el sur la creciente tiene el lado iluminado a la izquierda. En el hemisferio norte es al revés.", "forma");
q("luna", "¿Por qué vemos siempre la misma cara de la Luna?", ["Porque tarda lo mismo en girar sobre sí misma que en dar una vuelta a la Tierra", "Porque la Luna no rota", "Porque la Tierra tapa la otra cara", "Porque rota el doble de rápido que lo que gira alrededor de la Tierra"], "Es la rotación sincrónica, producida por las fuerzas de marea de la Tierra.", "cara");
q("luna", "De un día al siguiente, la Luna sale aproximadamente:", ["50 minutos más tarde", "50 minutos más temprano", "A la misma hora", "4 minutos más tarde"], "La Luna avanza unos 13° por día hacia el este en su órbita, y la Tierra tarda unos 50 minutos extra en «alcanzarla».", "horarios");
q("luna", "Si hoy hay Luna llena, ¿qué fase habrá dentro de una semana aproximadamente?", ["Cuarto menguante", "Cuarto creciente", "Luna nueva", "Luna llena"], "Entre fases principales pasa más o menos una semana: llena → cuarto menguante → nueva.", "ciclo");
q("luna", "¿A qué hora está más alta en el cielo (culmina) la Luna llena?", ["Cerca de medianoche", "Al mediodía", "Al atardecer", "Al amanecer"], "Está opuesta al Sol, así que culmina cuando el Sol está en su punto más bajo: a medianoche.", "horarios");
q("luna", "En cuarto creciente, el ángulo entre el Sol y la Luna visto desde la Tierra es de:", ["90°", "0°", "180°", "45°"], "En los cuartos la Luna está a 90° del Sol; vemos la mitad de su cara iluminada.", "causa");
q("luna", "¿Se puede ver la Luna de día?", ["Sí, en muchas fases; por ejemplo, en cuarto creciente por la tarde", "No, nunca", "Solo en Luna llena", "Solo durante los eclipses"], "El cuarto creciente sale cerca del mediodía y el menguante sigue visible de mañana.", "horarios");
q("luna", "La «cara oculta» de la Luna:", ["Recibe luz del Sol igual que la visible; solo que no la vemos desde la Tierra", "Está siempre a oscuras", "No existe", "Está cubierta de hielo"], "En Luna nueva, la cara oculta está totalmente iluminada. Por eso «lado oscuro» es un nombre engañoso.", "cara");
q("luna", "¿Cuál es el orden correcto de las fases a partir de la Luna nueva?", ["Cuarto creciente → llena → cuarto menguante", "Cuarto menguante → llena → cuarto creciente", "Llena → cuarto creciente → cuarto menguante", "Cuarto creciente → cuarto menguante → llena"], "Después de la nueva la parte iluminada crece hasta la llena y luego mengua.", "ciclo");

// ───────── Eclipses ─────────
q("eclipses", "¿Por qué no hay un eclipse de Sol en cada Luna nueva?", ["Porque la órbita de la Luna está inclinada unos 5° respecto a la eclíptica", "Porque la Luna es demasiado pequeña", "Porque la Tierra se mueve demasiado rápido", "Porque la Luna se está alejando"], "Casi siempre la Luna nueva pasa por encima o por debajo del Sol. Solo hay eclipse si está cerca de un nodo.", "nodos");
q("eclipses", "Un eclipse de Sol es anular (queda un anillo de Sol visible) cuando:", ["La Luna está cerca de su punto más lejano y se ve más chica que el Sol", "La Luna está en su punto más cercano a la Tierra", "La Tierra tapa parcialmente a la Luna", "Ocurre en Luna llena"], "Cerca del apogeo el disco lunar no alcanza a cubrir todo el Sol.", "solar");
q("eclipses", "Durante un eclipse total de Luna, la Luna se ve rojiza porque:", ["La atmósfera de la Tierra desvía luz del Sol hacia la sombra y deja pasar sobre todo el rojo", "La Luna se calienta", "Le llega la luz de Marte", "Hay volcanes activos en la Luna"], "Es el mismo efecto que pinta de rojo los atardeceres: la Luna recibe la luz de todos los amaneceres y atardeceres de la Tierra.", "lunar");
q("eclipses", "Un eclipse de Luna se puede ver desde:", ["Toda la mitad de la Tierra donde es de noche", "Solo una franja angosta", "Solo los polos", "Solo con telescopio"], "Cualquiera que tenga la Luna sobre el horizonte ve el eclipse. Los eclipses totales de Sol, en cambio, solo se ven en una franja.", "lunar");
q("eclipses", "Un eclipse total de Sol se ve como total desde:", ["Una franja angosta de la superficie terrestre", "Toda la mitad de la Tierra donde es de día", "Todo el planeta", "Solo el ecuador"], "La sombra total de la Luna (umbra) es pequeña: barre una franja de pocos cientos de kilómetros de ancho.", "solar");
q("eclipses", "¿Cuál es una forma segura de observar un eclipse parcial de Sol?", ["Con filtros certificados para observación solar o por proyección", "Con lentes de sol", "Mirando directo al atardecer", "A través de una radiografía o un vidrio ahumado"], "Ni lentes de sol, ni radiografías, ni vidrios ahumados protegen la vista.", "seguridad");
q("eclipses", "¿Cuánto puede durar como máximo la fase total de un eclipse de Sol?", ["Unos 7 minutos", "Unas 2 horas", "Un día", "Un segundo"], "La sombra de la Luna se mueve rápido sobre la Tierra. Los eclipses totales de Luna, en cambio, pueden durar más de una hora.", "solar");
q("eclipses", "¿Qué ciclo permite predecir la repetición de eclipses parecidos cada 18 años y 11 días?", ["El ciclo de Saros", "El ciclo metónico", "El ciclo de manchas solares", "El año bisiesto"], "Los babilonios ya lo conocían. El ciclo metónico (19 años) repite las fases lunares en las mismas fechas.", "nodos");
q("eclipses", "¿Por qué la Luna puede tapar justo al Sol en un eclipse total?", ["Porque el Sol es unas 400 veces más grande que la Luna, pero está unas 400 veces más lejos", "Porque la Luna es más grande que el Sol", "Porque la Luna está muy cerca del Sol", "Porque la Luna tiene sombra propia"], "Por esa coincidencia ambos se ven casi del mismo tamaño (medio grado) en el cielo.", "solar");
q("eclipses", "¿Cuántos eclipses de Sol (de algún tipo) ocurren como mínimo cada año?", ["2", "0", "1", "12"], "Hay al menos dos temporadas de eclipses por año, y en cada una hay al menos un eclipse de Sol, aunque sea parcial.", "nodos");
q("eclipses", "Un observador que está dentro de la umbra (sombra total) de la Luna ve un eclipse de Sol:", ["Total", "Parcial", "Anular", "De Luna"], "Desde la penumbra se vería parcial.", "solar");
q("eclipses", "¿Qué se puede ver durante la totalidad de un eclipse de Sol?", ["La corona solar", "La cara oculta de la Luna", "La sombra de la Tierra", "Las manchas solares con más detalle"], "Con el disco del Sol tapado aparece la tenue atmósfera exterior del Sol, la corona.", "solar");

// ───────── Calendario ─────────
q("calendario", "El año trópico (ciclo de las estaciones) dura aproximadamente:", ["365,2422 días", "365 días exactos", "360 días", "366 días"], "Unas 6 horas más que 365 días: por eso existen los años bisiestos.", "unidades");
q("calendario", "¿Cuál de estos años NO fue bisiesto?", ["1900", "2000", "2024", "1996"], "1900 es secular y no es divisible por 400. 2000 sí lo es.", "gregoriano");
q("calendario", "¿Cuál de estos años será bisiesto?", ["2400", "2100", "2200", "2300"], "De los seculares solo son bisiestos los divisibles por 400.", "gregoriano");
q("calendario", "La reforma gregoriana de 1582 se hizo porque:", ["El calendario juliano se había desfasado unos 10 días respecto al equinoccio", "La Luna había cambiado su órbita", "Faltaban meses en el año", "La Tierra había frenado su rotación"], "El año juliano (365,25 días) es algo más largo que el trópico y se atrasa 1 día cada unos 128 años.", "juliano");
q("calendario", "En la reforma gregoriana de 1582, después del jueves 4 de octubre vino el viernes:", ["15 de octubre", "5 de octubre", "14 de octubre", "1 de noviembre"], "Se suprimieron 10 días del calendario, pero la semana siguió su curso.", "gregoriano");
q("calendario", "En el calendario juliano, los años bisiestos son:", ["Uno cada 4 años, sin excepciones", "Uno cada 4 años, salvo los seculares no divisibles por 400", "Ninguno", "Uno cada 100 años"], "La excepción de los seculares es la corrección gregoriana.", "juliano");
q("calendario", "El calendario islámico es:", ["Lunar: 12 meses lunares, unos 354 días", "Solar, como el nuestro", "Lunisolar, como el hebreo", "Basado en las estrellas"], "Al tener 11 días menos que el año solar, sus fiestas recorren todas las estaciones.", "lunares");
q("calendario", "Cada huso horario corresponde a una franja de:", ["15° de longitud", "1° de longitud", "23,4° de longitud", "30° de longitud"], "La Tierra gira 360° en 24 h: 15° por hora.", "hora");
q("calendario", "En Montevideo el mediodía solar ocurre cerca de las 12:45 de la hora oficial. ¿Por qué?", ["Porque la hora oficial (UTC−3) corresponde al meridiano 45° O y Montevideo está unos 11° más al oeste", "Por el horario de verano", "Porque la Tierra gira más lento en Uruguay", "Porque el Sol se atrasa en invierno"], "11° × 4 minutos por grado ≈ 45 minutos de diferencia.", "hora");
q("calendario", "La duración de los meses de nuestro calendario (28 a 31 días) tiene su origen en:", ["El ciclo de fases de la Luna", "La rotación de la Tierra", "El movimiento de los planetas", "Las estaciones"], "«Mes» viene del ciclo lunar de 29,5 días, aunque nuestros meses ya no siguen a la Luna.", "unidades");
q("calendario", "La Semana de Turismo (Semana Santa) cambia de fecha cada año porque la Pascua se fija con:", ["El primer domingo después de la primera Luna llena posterior al equinoccio de marzo", "El solsticio de junio", "El 25 de diciembre", "La primera Luna nueva del año"], "Es una regla lunisolar: combina el equinoccio con las fases de la Luna.", "lunares");
q("calendario", "Los nombres lunes, martes, miércoles, jueves y viernes vienen de:", ["La Luna, Marte, Mercurio, Júpiter y Venus", "Cinco dioses griegos sin relación con los astros", "Los números del uno al cinco en latín", "Los meses del año"], "La semana de 7 días honra a los 7 astros que se mueven entre las estrellas a simple vista.", "unidades");
q("calendario", "¿Por qué se agrega un día en los años bisiestos?", ["Porque el año trópico dura casi 6 horas más que 365 días", "Porque la Tierra se frena cada 4 años", "Porque febrero es un mes corto", "Para que el año coincida con la Luna"], "4 × 6 h ≈ 1 día: cada 4 años se agrega el 29 de febrero.", "unidades");
q("calendario", "Un día solar es el tiempo entre:", ["Dos pasos consecutivos del Sol por el meridiano del lugar", "Dos salidas consecutivas de una misma estrella", "Una salida y una puesta del Sol", "Dos lunas llenas"], "Dura 24 h en promedio. Respecto a las estrellas la vuelta dura 23 h 56 min.", "unidades");

// ───────── Sistema Solar ─────────
q("sistema", "¿Cuántos planetas tiene el Sistema Solar?", ["8", "9", "7", "10"], "Mercurio, Venus, Tierra, Marte, Júpiter, Saturno, Urano y Neptuno. Plutón es un planeta enano desde 2006.", "estructura");
q("sistema", "En 2006 Plutón dejó de considerarse planeta porque:", ["No ha limpiado su órbita de otros cuerpos", "Es demasiado frío", "No gira alrededor del Sol", "No es casi esférico"], "Comparte su zona con muchos objetos del cinturón de Kuiper: es un planeta enano.", "planeta");
q("sistema", "¿Cuál es el planeta con la superficie más caliente?", ["Venus", "Mercurio", "Marte", "Júpiter"], "Su atmósfera de CO₂ produce un efecto invernadero enorme: unos 465 °C, más que Mercurio aunque esté más lejos del Sol.", "datos");
q("sistema", "El cinturón principal de asteroides está entre las órbitas de:", ["Marte y Júpiter", "La Tierra y Marte", "Neptuno y Plutón", "Júpiter y Saturno"], "Más allá de Neptuno está otro cinturón: el de Kuiper.", "estructura");
q("sistema", "¿Cuál es el planeta más grande del Sistema Solar?", ["Júpiter", "Saturno", "Neptuno", "La Tierra"], "Su diámetro es unas 11 veces el de la Tierra.", "datos");
q("sistema", "La cola de un cometa apunta siempre:", ["En dirección opuesta al Sol", "Hacia el Sol", "Hacia atrás de su movimiento", "Hacia la Tierra"], "La empujan la radiación y el viento solar. Cuando el cometa se aleja del Sol, la cola va «adelante».", "menores");
q("sistema", "Una «estrella fugaz» es:", ["Un meteoro: una partícula que se quema al entrar en la atmósfera", "Una estrella que cae", "Un satélite artificial", "Un cometa que explota"], "Si un fragmento sobrevive y llega al suelo, se llama meteorito.", "menores");
q("sistema", "¿Qué edad tiene aproximadamente el Sistema Solar?", ["4600 millones de años", "6000 años", "13 800 millones de años", "1 millón de años"], "13 800 millones de años es la edad del universo.", "origen");
q("sistema", "¿Por qué los planetas rocosos se formaron cerca del Sol?", ["Porque allí hacía demasiado calor para que se condensaran hielos y solo quedaron rocas y metales", "Porque allí había más gas", "Porque el Sol los atrajo después de formarse", "Porque los formaron choques de cometas"], "Más allá de la «línea de hielo» los planetas pudieron juntar hielo y gas y crecer como gigantes.", "origen");
q("sistema", "Según la segunda ley de Kepler, un planeta se mueve:", ["Más rápido cuando está más cerca del Sol", "Siempre a la misma velocidad", "Más rápido cuando está más lejos del Sol", "Solo cuando está cerca del Sol"], "La línea Sol–planeta barre áreas iguales en tiempos iguales.", "kepler");
q("sistema", "Según la tercera ley de Kepler, un planeta más lejano del Sol:", ["Tarda más en completar su órbita", "Tarda menos en completar su órbita", "Tarda lo mismo que los demás", "No completa ninguna órbita"], "T² ∝ a³: Neptuno tarda unos 165 años en dar una vuelta al Sol.", "kepler");
q("sistema", "¿Qué porcentaje de la masa del Sistema Solar está en el Sol?", ["Alrededor del 99,8 %", "Alrededor del 50 %", "Alrededor del 10 %", "Alrededor del 75 %"], "Todo el resto (planetas, lunas, asteroides, cometas) suma apenas un 0,2 %, la mayor parte en Júpiter.", "estructura");
q("sistema", "¿Qué planeta tiene el eje de rotación tan inclinado que parece «rodar» sobre su órbita?", ["Urano", "Saturno", "Venus", "Marte"], "Su eje está inclinado unos 98°.", "datos");
q("sistema", "Marte se ve rojizo porque:", ["Su superficie tiene óxido de hierro", "Su temperatura es muy alta", "Su atmósfera es de metano", "Refleja la luz de Júpiter"], "Es, literalmente, polvo oxidado.", "datos");
q("sistema", "El Sol obtiene su energía de:", ["La fusión nuclear de hidrógeno en helio en su núcleo", "La combustión de carbón", "La fisión de uranio", "Su enfriamiento"], "En el núcleo hay unos 15 millones de grados: suficiente para fusionar hidrógeno.", "origen");
q("sistema", "¿Qué planetas tienen anillos?", ["Los cuatro gigantes: Júpiter, Saturno, Urano y Neptuno", "Solo Saturno", "Solo Saturno y Júpiter", "Todos los planetas"], "Los de Saturno son los más brillantes; los demás son tenues y oscuros.", "datos");

// ═════════ Preguntas de las primeras etapas de la OUA (2021 a 2025) ═════════
// Las de 5 o 6 opciones se recortaron a 4 conservando la correcta. «(adaptada)» = se reformuló porque dependía de una imagen
// o la redacción original era imprecisa. Se descartaron las de pársec y magnitud absoluta (fuera del temario 2024).
const F25 = n => `OUA 2025/26, 1ª etapa, preg. ${n}`, F24 = n => `OUA 2024/25, 1ª etapa, preg. ${n}`, F23 = n => `OUA 2023/24, 1ª etapa, preg. ${n}`,
  F22 = n => `OUA 2022/23, 1ª etapa, preg. ${n}`, F21 = n => `OUA 2021/22, 1ª etapa, preg. ${n}`;

// Cielo y telescopios
q("cielo", "¿Cuál de estas estrellas no pertenece a la constelación de Orión?", ["Sirio", "Alnitak", "Mintaka", "Rígel"], "Sirio está en el Can Mayor. Alnitak y Mintaka son del cinturón (las Tres Marías) y Rígel es el pie de Orión.", "constelaciones", F25(11));
q("cielo", "¿A qué constelación pertenece la estrella Antares?", ["Escorpión", "Orión", "Cruz del Sur", "Tauro"], "Antares es la estrella roja del «corazón» del Escorpión.", "constelaciones", F24(1));
q("cielo", "¿Cuál de los siguientes objetos NO se considera visible a simple vista en el cielo nocturno?", ["Urano", "Mercurio", "Las Nubes de Magallanes", "Saturno"], "Urano está en el límite de visibilidad del ojo (magnitud 5,7) y en la práctica no se ve. Los otros sí se ven sin instrumentos.", "planetas", F24(2));
q("cielo", "¿Cuál de las siguientes afirmaciones es correcta respecto a un telescopio refractor?", ["Su óptica usa únicamente lentes", "Su óptica usa únicamente espejos", "No se le puede colocar un motor de seguimiento", "No presenta aberración cromática"], "El refractor usa lentes, y justamente por eso sí presenta aberración cromática.", "telescopios", F23(12));
q("cielo", "¿Cuál de estas estrellas es la más brillante vista desde la Tierra?", ["Canopus (m = −0,72)", "Arturo (m = −0,06)", "Rigel (m = +0,14)", "Acrux (m = +0,90)"], "La más brillante es la de magnitud menor: Canopus, con −0,72.", "magnitud", F22(4) + " (adaptada)");
q("cielo", "Un telescopio tiene un poder separador de 0,7″. ¿Cuál de estas estrellas dobles NO podría resolver?", ["Pórrima (separación 0,44″)", "Acrux (4″)", "Cástor (5,2″)", "Rigel (9″)"], "Solo puede separar estrellas más alejadas entre sí que 0,7″; Pórrima, con 0,44″, se ve como una sola.", "telescopios", F22(10));
q("cielo", "Una constelación es:", ["Una región del cielo con límites definidos", "Un grupo de estrellas unidas por su gravedad", "Un grupo imaginario de estrellas que forman figuras de objetos reales", "Un grupo de estrellas a similar distancia del Sol"], "La UAI divide todo el cielo en 88 regiones con límites oficiales. Sus estrellas no están ligadas ni a la misma distancia.", "constelaciones", F22(14));
q("cielo", "¿Cuál de estos defectos de la imagen NO está presente en un telescopio reflector?", ["La aberración cromática", "La aberración esférica", "La aberración de coma", "El astigmatismo"], "La aberración cromática aparece porque las lentes desvían distinto cada color; un espejo refleja todos los colores igual.", "telescopios", F21(3));
q("cielo", "¿Qué parte del telescopio puede tener un mecanismo que permita seguir a un astro?", ["La montura", "El tubo", "El objetivo", "El buscador"], "La montura sostiene y mueve el tubo; con un motor compensa la rotación de la Tierra.", "telescopios", F21(8));

// Movimiento diurno
q("diurno", "¿Cuál de estas constelaciones no puede ser circumpolar en ningún lugar del planeta?", ["Orión", "Osa Mayor", "Cruz del Sur", "Mosca"], "Orión está sobre el ecuador celeste, lejos de ambos polos. La Osa Mayor es circumpolar en el norte, y la Cruz y la Mosca en el sur.", "circumpolares", F25(3));
q("diurno", "¿Qué causa el movimiento aparente del Sol a lo largo del día?", ["La rotación de la Tierra sobre su eje", "El movimiento del Sol alrededor de la Tierra", "La traslación de la Tierra alrededor del Sol", "El movimiento de la Luna alrededor de la Tierra"], "La Tierra gira de oeste a este: el Sol y las estrellas parecen moverse de este a oeste.", "rotacion", F25(5));
q("diurno", "La altura de los polos celestes coincide con…", ["la latitud del observador", "la longitud del observador", "el cenit", "el punto cardinal norte o sur, según el hemisferio"], "En Montevideo (35° S) el polo sur celeste está a 35° sobre el horizonte.", "esfera", F25(12));
q("diurno", "¿Cuál de las siguientes afirmaciones es correcta?", ["Los astros describen trayectorias circulares paralelas al ecuador celeste", "Los astros describen trayectorias circulares paralelas al horizonte", "Cada astro recorre su arco a diferente velocidad angular", "En Uruguay todos los astros salen y se ponen"], "El cielo gira alrededor del eje del mundo, que es perpendicular al ecuador celeste. En Uruguay hay estrellas circumpolares.", "rotacion", F24(6));
q("diurno", "Estás en Punta del Este al atardecer del día del solsticio de Cáncer (junio) y quieres encontrar Sirio. ¿Hacia dónde miras?", ["Hacia el oeste", "Hacia el norte", "Hacia el sur", "Hacia el este"], "En junio el Sol está cerca de Sirio en el cielo, así que al atardecer Sirio está bajo, hacia el oeste, por donde se puso el Sol.", "sidereo", F24(7));
q("diurno", "Un observador en Montevideo ve el Escorpión alto en el cielo poco después de la puesta del Sol. ¿En qué estación es posible?", ["Invierno", "Verano", "Otoño", "Primavera"], "Las constelaciones visibles al anochecer cambian con el año; el Escorpión domina las noches de invierno.", "sidereo", F23(13));
q("diurno", "En un timelapse del cielo hacia el sur, desde Uruguay, los rastros de las estrellas forman arcos alrededor de un punto fijo. Ese punto es:", ["El polo celeste sur", "El punto cardinal sur", "Un punto que se mueve en el cielo", "El polo celeste norte"], "Todo el cielo gira alrededor del polo celeste; desde Uruguay el visible es el sur, unos 35° sobre el horizonte.", "rotacion", F22(2) + " (adaptada)");
q("diurno", "¿Cuál de las siguientes afirmaciones es correcta?", ["Todas las estrellas giran con la misma velocidad angular aparente", "Las estrellas cercanas a los polos giran más despacio que las cercanas al ecuador", "Los astros recorren circunferencias de igual radio", "Todos los astros salen por el este y se ponen por el oeste"], "Todas dan una vuelta por día (15° por hora); cambia el tamaño del círculo, no la velocidad angular. Las circumpolares no salen ni se ponen.", "rotacion", F21(4));

// Orientación
q("orientacion", "¿Qué usamos en el hemisferio sur para orientarnos durante la noche?", ["La Cruz del Sur", "La Osa Mayor", "La Luna", "Los planetas"], "Prolongando su eje mayor unas 4,5 veces se llega al polo sur celeste, y bajando al horizonte, al punto sur.", "cruz", F25(8));
q("orientacion", "¿Cuál de las siguientes afirmaciones es correcta?", ["El Sol sale por el este y se pone por el oeste en los equinoccios", "El Sol sale por el este y se pone por el oeste en los solsticios", "El Sol alcanza el cenit en Uruguay durante el verano", "El Sol sale por el este y se pone por el oeste todo el año"], "Solo en los equinoccios el Sol está sobre el ecuador celeste, que corta el horizonte en el este y el oeste.", "sol", F24(4));
q("orientacion", "Para ubicar el polo celeste sur se usan dos estrellas de la Cruz del Sur que están prácticamente alineadas con él. Son:", ["Acrux y Gacrux", "Mimosa y Acrux", "Acrux y Delta Crucis", "Mimosa y Gacrux"], "Gacrux (la cabeza) y Acrux (el pie) forman el eje mayor de la Cruz, que apunta al polo.", "cruz", F23(6));
q("orientacion", "¿Cuál de estas estrellas NO se usa en ningún método de orientación del hemisferio sur?", ["Polaris", "Achernar", "Acrux", "Gacrux"], "Polaris, la estrella Polar, marca el norte pero desde el hemisferio sur no se ve.", "cruz", F23(10));
q("orientacion", "El Sol está a altura 0° con acimut 90°, medido desde el sur hacia el oeste. ¿Dónde está?", ["En el punto cardinal oeste", "En el punto cardinal este", "En el punto cardinal norte", "En el cenit"], "Altura 0° es el horizonte. Con acimut contado desde el sur hacia el oeste, 90° es el oeste: el Sol se está poniendo en un equinoccio.", "brujula", F22(9));
q("orientacion", "¿Qué punto notable del cielo está aproximadamente en el punto medio entre Acrux y Achernar?", ["El polo sur celeste", "El punto cardinal sur", "El ecuador celeste", "El cenit"], "Es un segundo método para hallar el polo, que sirve de control del método de la Cruz del Sur.", "cruz", F21(2));

// UA y año luz
q("distancias", "Una unidad astronómica equivale a:", ["La distancia Tierra–Sol", "La distancia Tierra–Luna", "La distancia Tierra–Marte", "La distancia que recorre la luz en un año"], "Es la distancia media Tierra–Sol, unos 150 millones de km. La que recorre la luz en un año es el año luz.", "ua", F25(9));

// Estaciones y Sol
q("estaciones", "El invierno del hemisferio sur empieza alrededor del 21 de junio. El cambio de estación se debe a:", ["La inclinación del eje terrestre, que hace que el hemisferio norte reciba más luz que el sur", "Que estamos cerca del afelio y la Tierra está algo más lejos del Sol", "Que estamos cerca del perihelio y la Tierra está algo más cerca del Sol", "La inclinación del eje terrestre, que hace que el hemisferio sur reciba más luz que el norte"], "En junio el hemisferio sur está inclinado en dirección contraria al Sol: los rayos le llegan más oblicuos y por menos horas.", "causa", F25(10));
q("estaciones", "¿Cuál de estos fenómenos NO está relacionado con las estaciones?", ["La leve variación de la distancia Tierra–Sol durante el año", "La inclinación del eje terrestre", "La variación de la incidencia de los rayos solares en una latitud", "Los solsticios y equinoccios"], "La distancia varía poco y además la Tierra está más cerca del Sol en enero, en pleno verano austral.", "causa", F23(2));
q("estaciones", "El día del solsticio de Cáncer (junio), para un observador en Uruguay, el Sol:", ["Sale desplazado hacia el norte del punto este y alcanza su menor altura de culminación del año", "Sale desplazado hacia el norte del punto este y alcanza su mayor altura de culminación del año", "Sale exactamente por el este y recorre el ecuador celeste", "Sale desplazado hacia el sur del punto este y alcanza su menor altura de culminación del año"], "En junio el Sol está 23,4° al norte del ecuador celeste: sale por el noreste y al mediodía está a solo unos 31° de altura en Montevideo.", "altura", F23(8) + " (adaptada)");
q("estaciones", "¿Cuál de estas afirmaciones es cierta para un observador en Montevideo (latitud 35° S)?", ["El Sol alcanza su mayor altura de culminación el día del solsticio de verano", "El Sol alcanza el cenit el día del solsticio de verano", "A partir del solsticio de invierno las noches se alargan", "A partir del equinoccio de otoño, la salida y la puesta del Sol se desplazan del este hacia el sur"], "En diciembre culmina a unos 78°, nunca en el cenit. Después del solsticio de invierno los días se alargan, y desde el otoño la salida se desplaza hacia el norte.", "altura", F21(10));

// Fases de la Luna
q("luna", "¿Cómo se llama la fase en la que la Luna nos muestra toda su cara iluminada?", ["Luna llena", "Luna completa", "Luna nueva", "Luna iluminada"], "En Luna llena la Luna está opuesta al Sol y vemos completa su mitad iluminada.", "ciclo", F25(7));
q("luna", "Estás en una playa de Piriápolis y la Luna está llena. ¿Cuánto tiempo pasará hasta que vuelva a estar llena?", ["29,5 días", "27,3 días", "30,4 días", "31,1 días"], "Es el mes sinódico. 27,3 días es la vuelta respecto a las estrellas: hace falta algo más porque la Tierra también avanzó alrededor del Sol.", "ciclo", F24(9));
q("luna", "Quieres organizar una observación en La Paloma con la Luna en cuarto creciente. ¿Cuántos días después de la Luna llena deberías programarla?", ["21 días", "3 días", "7 días", "14 días"], "Llena → cuarto menguante (~7 días) → nueva (~15) → cuarto creciente (~22).", "ciclo", F24(14));
q("luna", "Si la Luna llena acaba de salir:", ["El Sol acaba de ponerse", "Es medianoche", "Es mediodía", "Está amaneciendo"], "La Luna llena está opuesta al Sol: sale por el este cuando el Sol se pone por el oeste.", "horarios", F23(11));

// Eclipses
q("eclipses", "¿En qué fase debe estar la Luna para que pueda darse un eclipse solar?", ["Nueva", "Cuarto creciente", "Llena", "Cuarto menguante"], "La Luna tiene que pasar entre el Sol y la Tierra, que es la posición de Luna nueva.", "tipos", F25(4));
q("eclipses", "Durante un eclipse de Sol es correcto afirmar que:", ["La Luna proyecta su sombra sobre la Tierra", "La Tierra proyecta su sombra sobre el Sol", "Lo ven todos los que tienen al Sol sobre el horizonte", "Sol, Tierra y Luna están alineados en ese orden"], "El orden es Sol–Luna–Tierra, y solo lo ven quienes están dentro de la sombra o la penumbra de la Luna.", "tipos", F24(5));
q("eclipses", "Escuchas que esta noche habrá un eclipse de Luna. ¿En qué fase está la Luna?", ["Luna llena", "Luna nueva", "Cuarto creciente", "Cuarto menguante"], "La sombra de la Tierra solo puede caer sobre la Luna cuando la Luna está opuesta al Sol.", "tipos", F24(10));

// Calendario
q("calendario", "Para que un año sea bisiesto se debe cumplir que:", ["Sea divisible entre 4 y, en los cambios de siglo, entre 400", "Sea divisible entre 4 y, en los cambios de siglo, entre 100", "Sea divisible entre 4, sin excepciones", "Sea divisible entre 2"], "La regla gregoriana: 2000 fue bisiesto (divisible por 400) pero 1900 no.", "gregoriano", F25(2));
q("calendario", "¿Qué regla explica que 2028 tenga un 29 de febrero?", ["Un año es bisiesto si es divisible por 4, pero no por 100, salvo que sea divisible por 400", "Un año es bisiesto si es divisible por 100", "Un año es bisiesto si es divisible por 400", "Un año es bisiesto si es divisible por 4 y por 100"], "2028 es divisible por 4 y no es secular, así que es bisiesto.", "gregoriano", F24(11));

// Sistema Solar
q("sistema", "¿Cuál de estos planetas tiene más satélites?", ["Júpiter", "Venus", "Marte", "Urano"], "Júpiter tiene decenas de lunas. Venus no tiene, Marte tiene 2 y Urano unas 28. (El que más tiene es Saturno, que no está entre las opciones.)", "datos", F25(1));
q("sistema", "¿Qué tipo de planetas son Júpiter y Saturno?", ["Gigantes gaseosos", "Gigantes rocosos", "Enanos rocosos", "Enanos gaseosos"], "Son enormes y están formados sobre todo por hidrógeno y helio.", "estructura", F25(6));
q("sistema", "¿Qué opción ordena los objetos por distancia creciente al Sol?", ["Planetas rocosos, cinturón de asteroides, planetas gaseosos, cinturón de Kuiper", "Planetas rocosos, cinturón de Kuiper, planetas gaseosos, cinturón de asteroides", "Planetas gaseosos, cinturón de asteroides, planetas rocosos, cinturón de Kuiper", "Planetas rocosos, planetas gaseosos, cinturón de asteroides, cinturón de Kuiper"], "El cinturón de asteroides está entre Marte y Júpiter, y el de Kuiper más allá de Neptuno.", "estructura", F24(3));
q("sistema", "¿Cuál es el planeta con más lunas (satélites naturales) conocidas?", ["Saturno", "Marte", "Júpiter", "Urano"], "Saturno superó a Júpiter con los descubrimientos recientes y tiene más de 270 lunas conocidas.", "datos", F24(12));
q("sistema", "¿Cuál de estas afirmaciones sobre las lunas galileanas de Júpiter es correcta?", ["Ío es la luna con más actividad volcánica del Sistema Solar", "Ganímedes es la luna más pequeña de Júpiter", "Europa tiene montañas más altas que las de la Tierra", "Calisto tiene la atmósfera más densa de las lunas galileanas"], "Las mareas de Júpiter calientan el interior de Ío. Ganímedes es, al revés, la luna más grande del Sistema Solar.", "datos", F24(13));
q("sistema", "Unos estudiantes ven un objeto luminoso que cruza el cielo nocturno dejando un rastro de luz. ¿Cómo se clasifica?", ["Es un meteoro: el rastro luminoso que deja un cuerpo al entrar en la atmósfera", "Es un meteorito, porque está en la superficie de un planeta", "Es un meteoroide, porque orbita alrededor del Sol", "Es un meteorito, porque es el rastro que deja al entrar en la atmósfera"], "Meteoroide: el cuerpo en el espacio. Meteoro: el fenómeno luminoso. Meteorito: lo que llega al suelo.", "menores", F23(5));

// ═════════ Cobertura del programa de Astronomía 1° EMS (2026) dentro de los temas de la OUA ═════════
// Objetivo: que saber todas las respuestas equivalga a conocer el tema. Sin ejercicios con cuentas.
function seccion(tema, id, titulo, texto) { TEMAS.find(t => t.id === tema).teoria.push({ id, titulo, texto }); }

seccion("cielo", "cultural", "Constelaciones y astronomía cultural",
  "Las constelaciones del hemisferio norte vienen sobre todo de la tradición griega: Ptolomeo listó 48. Las del cielo austral, invisibles desde Europa, las nombraron navegantes y astrónomos europeos entre los siglos XVI y XVIII; Lacaille, por ejemplo, les puso nombres de instrumentos (Telescopio, Microscopio, Compás). Cada cultura vio sus propias figuras. Los pueblos andinos y los aborígenes australianos reconocían <b>constelaciones oscuras</b>, formadas por las nubes de polvo de la Vía Láctea: la llama de los incas tiene como ojos a Alfa y Beta Centauri, y la cabeza del emú australiano es el <b>Saco de Carbón</b>, junto a la Cruz del Sur. Las <b>Pléyades</b> marcaron calendarios agrícolas y fiestas en muchas culturas. En el mito griego, Orión murió por la picadura del Escorpión y por eso los dos fueron puestos en lados <b>opuestos</b> del cielo: cuando uno sale, el otro se pone.");
seccion("cielo", "pseudociencia", "Astronomía y pseudociencia",
  "La <b>astronomía</b> es una ciencia: explica los astros con observaciones y modelos que se ponen a prueba. La <b>astrología</b> afirma que la posición de los astros influye en la personalidad o el destino, pero no tiene ninguna evidencia a favor. Además, por la <b>precesión</b> del eje terrestre (un giro lento de unos 26 000 años), las fechas de los «signos» ya no coinciden con la constelación donde realmente está el Sol, y el Sol también atraviesa una 13.ª constelación, <b>Ofiuco</b>. La «<b>superluna</b>» es una Luna llena cerca del perigeo: se ve algo más grande y brillante, pero no causa terremotos ni otros desastres. Las «alineaciones planetarias» tampoco producen efectos apreciables en la Tierra.");
seccion("cielo", "satelites", "Satélites artificiales y otros puntos que se mueven",
  "Un <b>satélite artificial</b> se ve como un punto que cruza el cielo en pocos minutos, a velocidad constante y sin parpadear. Se ven sobre todo poco después del atardecer o antes del amanecer: el suelo ya está a oscuras pero el satélite, a cientos de kilómetros de altura, todavía recibe luz del Sol, que refleja. Si entra en la sombra de la Tierra, se «apaga» de golpe. La <b>Estación Espacial Internacional</b> orbita a unos 400 km, da una vuelta cada hora y media y es de lo más brillante del cielo. Los satélites Starlink recién lanzados se ven como un «tren» de puntos en fila. Los aviones, en cambio, tienen luces de colores que titilan.");
seccion("cielo", "contaminacion", "Contaminación lumínica",
  "La <b>contaminación lumínica</b> es la luz artificial mal dirigida o excesiva que ilumina la atmósfera de noche. Aclara el fondo del cielo y borra las estrellas débiles: en una ciudad se ven pocas decenas de estrellas y no se ve la Vía Láctea, mientras que en el campo se ven miles. También desperdicia energía y altera a muchos animales (aves migratorias, tortugas marinas, insectos). Se reduce con luminarias que apunten <b>hacia abajo</b>, luz de tono cálido, menos intensidad y apagando lo innecesario. Para observar, conviene alejarse de las luces y esperar unos 20 minutos a que la vista se adapte a la oscuridad.");
seccion("cielo", "espaciales", "Telescopios en el espacio y grandes observatorios",
  "La atmósfera hace <b>titilar</b> las estrellas (por su turbulencia) y bloquea buena parte del infrarrojo, el ultravioleta y los rayos X. Por eso se ponen telescopios en el espacio. El <b>Hubble</b> (1990) orbita a unos 540 km y observa sobre todo en luz visible y ultravioleta. El <b>James Webb</b> (lanzado en 2021) observa en <b>infrarrojo</b>, tiene un espejo de 6,5 m y está a 1,5 millones de km de la Tierra; ve galaxias muy lejanas y estrellas que se forman dentro de nubes de polvo. En tierra, los grandes observatorios se construyen en lugares altos, secos y oscuros, como el desierto de Atacama, en Chile. En Uruguay, el Observatorio Astronómico Los Molinos (Montevideo) ha descubierto asteroides.");
seccion("cielo", "estrellas", "Color y titileo de las estrellas",
  "Las estrellas tienen colores: las <b>rojizas</b> (Antares, Betelgeuse) son <b>más frías</b> en su superficie y las <b>azuladas</b> (Rigel) <b>más calientes</b>; el Sol es amarillento. Las estrellas titilan porque su luz llega como un punto y la turbulencia del aire la desvía; los planetas, que se ven como pequeños discos, titilan menos. De día no vemos estrellas porque la atmósfera dispersa la luz del Sol y el cielo brillante las tapa. La Luna llena tiene magnitud −12,7 y el Sol −26,7.");
seccion("cielo", "profundo", "Cielo profundo desde Uruguay",
  "El <b>centro de la Vía Láctea</b> está en dirección a <b>Sagitario</b>, junto al Escorpión: la parte más brillante de la franja se ve alta en las noches de <b>invierno</b>. Junto a la Cruz del Sur está el <b>Saco de Carbón</b>, una nebulosa oscura de polvo que tapa las estrellas de atrás. Los <b>cúmulos abiertos</b> (como las Pléyades) tienen estrellas jóvenes y sueltas; los <b>cúmulos globulares</b>, esferas de cientos de miles de estrellas viejas, como <b>Omega Centauri</b> y 47 Tucanae, visibles a simple vista desde el sur. La <b>Nebulosa de Orión</b>, bajo las Tres Marías, es una región donde nacen estrellas. La galaxia de <b>Andrómeda</b> es el objeto más lejano que se ve a simple vista.");

seccion("orientacion", "reloj", "Relojes de sol y otras señales",
  "Un <b>reloj de sol</b> marca la <b>hora solar</b>, no la hora oficial: en Montevideo atrasa unos 45 minutos respecto al reloj (y varía unos minutos según la época). Para que funcione todo el año, su gnomon debe ser <b>paralelo al eje de la Tierra</b>: apuntar al polo celeste (en Uruguay, al sur) con una inclinación igual a la latitud. Las Tres Marías están sobre el <b>ecuador celeste</b>: salen exactamente por el <b>este</b> y se ponen por el oeste, así que sirven para orientarse. La Cruz del Sur gira alrededor del polo durante la noche (a veces se ve «acostada» o «de cabeza»), pero su eje mayor siempre apunta al polo. Desde Montevideo la Cruz es circumpolar: nunca se pone.");

seccion("distancias", "escala", "La escala del Universo",
  "Usamos la unidad que deja números manejables: <b>km</b> para la Tierra y la Luna, <b>UA</b> para el Sistema Solar y <b>años luz</b> para estrellas y galaxias. El año luz es mucho mayor que la UA. Neptuno está a 30 UA, pero la <b>nube de Oort</b>, el borde del Sistema Solar, se extiende hasta alrededor de un año luz. La luz no llega al instante: si el Sol se apagara, lo notaríamos recién unos 8 minutos después, y cuando miramos Andrómeda la vemos como era hace unos 2,5 millones de años. Nada viaja más rápido que la luz.");

seccion("estaciones", "orbita", "La órbita de la Tierra y la duración de las estaciones",
  "Por la <b>1.ª ley de Kepler</b>, la órbita de la Tierra es una <b>elipse</b> con el Sol en un foco, pero es casi circular: la distancia al Sol varía solo un 3 %, demasiado poco para causar las estaciones. Por la <b>2.ª ley</b>, la Tierra va más rápido cerca del perihelio (enero). Por eso las estaciones no duran lo mismo: el <b>verano austral</b> (diciembre–marzo) es la estación <b>más corta</b> (unos 89 días) y el <b>invierno austral</b> la más larga (unos 93 días).");
seccion("estaciones", "dia", "Duración del día, sombras y puntos de salida",
  "En verano los días son más largos y las sombras del mediodía más cortas; en invierno, al revés. En los equinoccios el día dura unas 12 horas en todo el planeta, y en el <b>ecuador</b> dura casi 12 horas todo el año. Dentro de los <b>círculos polares</b> hay días de verano en que el Sol no se pone (<b>Sol de medianoche</b>) y días de invierno en que no sale. A lo largo del año el punto de salida del Sol se desplaza por el horizonte, entre el noreste (en junio) y el sudeste (en diciembre). «Solsticio» quiere decir «Sol quieto»: el punto de salida deja de desplazarse y empieza a volver. En el hemisferio sur, el equinoccio de marzo marca el comienzo del <b>otoño</b> y el de setiembre el de la <b>primavera</b>.");

seccion("luna", "movimiento", "La Luna entre las estrellas",
  "La Luna se desplaza hacia el <b>este</b> entre las estrellas unos <b>13° por día</b> (unas 26 veces su propio diámetro), por eso sale cada día más tarde. Su lado iluminado <b>siempre apunta hacia el Sol</b>. Todos los habitantes de la Tierra ven la <b>misma fase</b> el mismo día (aunque orientada distinto según el hemisferio). En la creciente fina se ve tenue la parte «oscura»: es la <b>luz cenicienta</b>, luz del Sol reflejada por la Tierra. Vista desde la Luna, la Tierra también tiene fases, opuestas a las lunares: cuando aquí hay Luna llena, allá hay «Tierra nueva». La distancia a la Luna varía entre el perigeo (más cerca) y el apogeo (más lejos).");

seccion("eclipses", "visibilidad", "Dónde y cómo se ven los eclipses",
  "La sombra de la Luna recorre la Tierra de <b>oeste a este</b> en unas pocas horas: en un mapa de un eclipse de Sol, la <b>franja de totalidad</b> es una banda angosta y a sus costados, en una zona mucho más amplia, el eclipse se ve <b>parcial</b>. En un lugar fijo, un eclipse total de Sol se repite en promedio cada unos <b>375 años</b>. Durante la totalidad baja la temperatura, se ven los planetas y las estrellas brillantes, y los animales se comportan como al anochecer. Un eclipse de Luna ocurre en el <b>mismo instante para todos</b> los que tienen la Luna sobre el horizonte (a distinta hora local). Cuando la Luna solo pasa por la penumbra terrestre, el eclipse es <b>penumbral</b> y apenas se nota.");
seccion("eclipses", "cultural", "Los eclipses en la historia",
  "Muchas culturas explicaban los eclipses de Sol con un animal o un monstruo que devoraba al Sol, y los vivían como presagios. Según la tradición griega, Tales de Mileto predijo un eclipse en el 585 a. C. <b>Aristóteles</b> notó que la sombra de la Tierra sobre la Luna en los eclipses es siempre <b>curva</b> y lo usó como prueba de que la Tierra es esférica. En el eclipse de <b>1919</b> se midió que la luz de las estrellas se desvía al pasar cerca del Sol, lo que confirmó la teoría de la relatividad general de Einstein.");

seccion("calendario", "historia", "Historia del calendario",
  "Los <b>egipcios</b> usaban un año de 365 días; la salida de <b>Sirio</b> antes del amanecer anunciaba la crecida del Nilo. El año romano empezaba en marzo: por eso <b>setiembre</b>, octubre, noviembre y diciembre significan séptimo, octavo, noveno y décimo mes. <b>Julio</b> y <b>agosto</b> homenajean a Julio César y a Augusto. El mediodía solar no cae todos los días a la misma hora del reloj: la <b>ecuación del tiempo</b> lo adelanta o atrasa hasta unos 16 minutos a lo largo del año, porque la órbita es elíptica y el eje está inclinado. La <b>línea internacional de cambio de fecha</b> está cerca del meridiano 180°: al cruzarla se suma o se resta un día.");
seccion("calendario", "precesion", "Precesión: año trópico y año sidéreo",
  "El eje de la Tierra gira lentamente como un trompo, completando una vuelta en unos <b>26 000 años</b> (<b>precesión</b>). Por eso los equinoccios se desplazan poco a poco entre las estrellas, el año de las estaciones (<b>trópico</b>) es unos 20 minutos más corto que la vuelta completa respecto a las estrellas (<b>año sidéreo</b>), y dentro de miles de años la «estrella polar» será otra. El calendario sigue el año trópico porque lo que importa es que las estaciones caigan siempre en las mismas fechas.");

seccion("sistema", "comparada", "Planetología comparada",
  "<b>Planetas interiores</b> son los que orbitan más cerca del Sol que la Tierra (Mercurio y Venus); los demás, <b>exteriores</b>. Los rocosos tienen <b>núcleo metálico, manto y corteza</b>; los gigantes no tienen superficie sólida. La Tierra es el planeta más <b>denso</b>; Saturno es el menos denso, menos que el agua. <b>Júpiter</b> rota más rápido que ningún otro planeta (un día de unas 10 h). <b>Venus</b> rota al revés y tan despacio que su día dura más que su año. Mercurio y Venus no tienen lunas; Marte tiene dos pequeñas, Fobos y Deimos.");
seccion("sistema", "geologia", "Superficies y atmósferas",
  "Mercurio y la Luna están llenos de <b>cráteres</b> porque casi no tienen atmósfera ni actividad que los borre. Mercurio, sin atmósfera que guarde el calor, pasa de unos 430 °C de día a −180 °C de noche. Marte tiene el volcán más grande conocido, el <b>Olimpo</b> (Olympus Mons), un enorme cañón (Valles Marineris), <b>casquetes polares</b> de hielo de agua y de CO₂, y una atmósfera <b>muy tenue</b> de CO₂; en el pasado tuvo agua líquida en su superficie. La Tierra es el único planeta conocido con <b>tectónica de placas</b> activa. Venus tiene una atmósfera densísima de CO₂ con nubes de ácido sulfúrico. En Júpiter, la <b>Gran Mancha Roja</b> es una tormenta más grande que la Tierra que se observa desde hace más de 150 años; Neptuno tiene los vientos más rápidos del Sistema Solar.");
seccion("sistema", "lunas", "Satélites y planetas enanos",
  "<b>Ganímedes</b> (Júpiter) es la luna más grande del Sistema Solar, mayor que Mercurio. <b>Titán</b> (Saturno) es la única luna con una atmósfera densa, de nitrógeno, y tiene lagos de metano. <b>Europa</b> (Júpiter) y <b>Encélado</b> (Saturno) tienen océanos de agua bajo el hielo; Encélado lanza chorros de agua al espacio. Además de Plutón (que tiene una luna grande, Caronte), son planetas enanos <b>Ceres</b>, el mayor objeto del cinturón de asteroides, y <b>Eris</b>, más allá de Neptuno. Todo lo que no es planeta, planeta enano ni satélite (asteroides, cometas, transneptunianos) es un <b>cuerpo menor</b>.");
seccion("sistema", "cometas", "Cometas y lluvias de meteoros",
  "Los cometas de período corto vienen del <b>cinturón de Kuiper</b>; los de período largo, de la lejana <b>nube de Oort</b>. El cometa <b>Halley</b> vuelve cada unos 76 años (el próximo paso es en 2061). Las <b>lluvias de meteoros</b> ocurren cuando la Tierra cruza los restos que dejó un cometa en su órbita; por eso se repiten en las mismas fechas cada año, como las Perseidas en agosto. Por perspectiva, los meteoros de una lluvia parecen salir de un mismo punto del cielo, el <b>radiante</b>, que le da nombre.");
seccion("sistema", "exploracion", "Exploración: sondas y rovers",
  "La <b>Voyager 1</b> (1977) es el objeto humano más lejano: ya salió de la burbuja del viento solar, al espacio interestelar. <b>New Horizons</b> sobrevoló Plutón en 2015 y mostró su superficie por primera vez. <b>Cassini</b> estudió Saturno y sus lunas hasta 2017. <b>Juno</b> llegó a Júpiter en 2016 para estudiar su interior y su atmósfera. El rover <b>Perseverance</b> llegó a Marte en 2021 para buscar señales de vida pasada y juntar muestras de rocas. La <b>Parker Solar Probe</b> es la nave que más se acercó al Sol. Las sondas permiten estudiar de cerca lo que desde la Tierra se ve como un punto.");
seccion("sistema", "habitable", "La Tierra, un mundo habitable",
  "La Tierra es el único lugar donde sabemos que hay vida. Tiene <b>agua líquida</b> en la superficie porque está a la distancia justa del Sol (en la <b>zona de habitabilidad</b>), una atmósfera que regula la temperatura y un <b>campo magnético</b> que la protege del viento solar. Venus muestra lo que pasa con un efecto invernadero desbocado, y Marte, lo que pasa al perder casi toda la atmósfera. Por eso cuidar la Tierra es cuidar el único mundo habitable que conocemos.");
seccion("sistema", "formacion", "Formación de la Luna y futuro del Sol",
  "La edad del Sistema Solar (unos 4600 millones de años) se mide datando con radiactividad los <b>meteoritos</b> más antiguos. En el disco que rodeaba al Sol joven, el polvo se juntó en <b>planetesimales</b>, que chocaron y crecieron hasta formar los planetas (acreción). Al principio hubo muchísimos impactos: de esa época son la mayoría de los cráteres. La Luna se habría formado por un <b>gran impacto</b> de un cuerpo del tamaño de Marte contra la Tierra joven. Dentro de unos 5000 millones de años el Sol se hinchará como <b>gigante roja</b>, engullirá a Mercurio y Venus (quizás a la Tierra) y terminará como <b>enana blanca</b>. No tiene masa suficiente para explotar como supernova.");

// ───── Cielo a simple vista ─────
q("cielo", "Las constelaciones del cielo austral, como Telescopio, Microscopio o Compás, fueron nombradas:", ["Por astrónomos y navegantes europeos entre los siglos XVI y XVIII", "Por los griegos de la Antigüedad", "Por los pueblos originarios de Uruguay", "Por la NASA en el siglo XX"], "Desde Europa no se ven; las nombraron quienes viajaron al hemisferio sur, como Lacaille.", "cultural");
q("cielo", "Los incas veían en la Vía Láctea una «llama» cuyos ojos son Alfa y Beta Centauri. Esa figura es un ejemplo de:", ["Una constelación oscura, formada por nubes de polvo de la Vía Láctea", "Un asterismo de estrellas brillantes", "Una constelación oficial de la UAI", "Un cúmulo globular"], "Muchos pueblos del sur veían figuras en las manchas oscuras de la Vía Láctea, no solo en las estrellas.", "cultural");
q("cielo", "¿Por qué en el mito griego Orión y el Escorpión están en lados opuestos del cielo?", ["Porque el Escorpión mató a Orión, y así nunca se encuentran: cuando uno sale, el otro se pone", "Porque los dos son constelaciones circumpolares", "Porque Orión solo se ve desde el hemisferio norte", "Porque el Escorpión está en la Vía Láctea y Orión no"], "Están separados unos 180° en el cielo: Orión domina el verano austral y el Escorpión el invierno.", "cultural");
q("cielo", "Las Pléyades, en muchas culturas antiguas, se usaban para:", ["Marcar el calendario agrícola y las fiestas del año", "Encontrar el polo sur celeste", "Predecir eclipses de Sol", "Medir la distancia a la Luna"], "Su aparición en ciertas épocas del año marcaba siembras, cosechas o el año nuevo.", "cultural");
q("cielo", "¿Qué diferencia a la astronomía de la astrología?", ["La astronomía pone a prueba sus explicaciones con observaciones; la astrología no tiene evidencia que la respalde", "La astrología estudia los planetas y la astronomía las estrellas", "Son lo mismo con distinto nombre", "La astrología usa telescopios y la astronomía no"], "Los estudios controlados no encuentran relación entre la posición de los astros al nacer y la personalidad o el destino.", "pseudociencia");
q("cielo", "Alguien nació el 1 de abril y su «signo» es Aries. ¿En qué constelación estaba realmente el Sol ese día?", ["En Piscis, porque la precesión desplazó los signos respecto a las constelaciones", "En Aries, siempre coinciden", "En Libra, la constelación opuesta", "En ninguna, el Sol no pasa por constelaciones"], "Las fechas de los signos se fijaron hace unos 2000 años; desde entonces la precesión las corrió casi una constelación entera.", "pseudociencia");
q("cielo", "¿Cuántas constelaciones atraviesa realmente el Sol a lo largo del año sobre la eclíptica?", ["13, porque también pasa por Ofiuco", "12, las del zodíaco", "88, todas", "4, una por estación"], "Con los límites oficiales de la UAI, la eclíptica también cruza Ofiuco, que la astrología no cuenta.", "pseudociencia");
q("cielo", "Una «superluna» es:", ["Una Luna llena cerca del perigeo, que se ve algo más grande y brillante, sin efectos en la vida cotidiana", "Una Luna llena que provoca terremotos", "Un eclipse total de Luna", "La segunda Luna llena de un mismo mes"], "En el perigeo la Luna se ve hasta un 14 % más grande que en el apogeo, pero eso no causa desastres.", "pseudociencia");
q("cielo", "Un video en redes dice que una «alineación de planetas» va a provocar catástrofes en la Tierra. ¿Qué responde la astronomía?", ["Que los planetas están demasiado lejos y su efecto gravitatorio sobre la Tierra es despreciable", "Que es cierto, porque su gravedad se suma", "Que solo afecta a las mareas del océano Pacífico", "Que depende del signo zodiacal de cada persona"], "Incluso juntos, los planetas atraen a la Tierra muchísimo menos que la Luna. Ante noticias así, conviene buscar la fuente y la evidencia.", "pseudociencia");
q("cielo", "Poco después del atardecer ves un punto brillante que cruza el cielo en unos minutos, sin parpadear. Probablemente es:", ["Un satélite artificial, como la Estación Espacial Internacional", "Un planeta", "Una estrella fugaz", "Un avión"], "Los aviones tienen luces de colores que titilan; los meteoros duran un segundo; los planetas no se mueven a simple vista en minutos.", "satelites");
q("cielo", "¿Por qué los satélites artificiales se ven sobre todo poco después del atardecer o antes del amanecer?", ["Porque el suelo ya está a oscuras pero el satélite, muy alto, todavía recibe y refleja la luz del Sol", "Porque solo orbitan a esas horas", "Porque tienen luces propias que se encienden de noche", "Porque a medianoche están detrás de la Luna"], "A medianoche suelen estar dentro de la sombra de la Tierra y no reflejan luz.", "satelites");
q("cielo", "Mientras sigues un satélite con la vista, de repente desaparece en medio del cielo. ¿Qué pasó?", ["Entró en la sombra de la Tierra y dejó de reflejar la luz del Sol", "Se desintegró en la atmósfera", "Apagó sus luces", "Lo tapó una estrella"], "Los satélites brillan por luz solar reflejada; al entrar en la sombra terrestre se «apagan».", "satelites");
q("cielo", "Una fila de muchos puntos que avanzan uno detrás del otro por el cielo suele ser:", ["Un «tren» de satélites Starlink recién lanzados", "Una lluvia de meteoros", "Un cometa partiéndose", "Una constelación en movimiento"], "Después de cada lanzamiento, los satélites van juntos en fila hasta llegar a su órbita final.", "satelites");
q("cielo", "¿Qué es la contaminación lumínica?", ["La luz artificial excesiva o mal dirigida que ilumina el cielo nocturno y oculta las estrellas débiles", "El humo de las fábricas que tapa las estrellas", "La luz de la Luna llena", "La radiación de los satélites"], "Aclara el fondo del cielo: en una ciudad se ven unas pocas decenas de estrellas y en el campo, miles.", "contaminacion");
q("cielo", "¿Cuál de estas medidas reduce la contaminación lumínica?", ["Usar luminarias que apunten hacia abajo y apagar las luces innecesarias", "Usar luces más potentes y blancas", "Iluminar los edificios de abajo hacia arriba", "Dejar encendido el alumbrado todo el día"], "La luz que se escapa hacia arriba no ilumina nada útil y aclara el cielo.", "contaminacion");
q("cielo", "Además de impedir ver las estrellas, la contaminación lumínica:", ["Desperdicia energía y altera a animales como aves migratorias, tortugas e insectos", "Aumenta los eclipses", "Hace que la Luna se vea más chica", "No tiene otros efectos"], "Muchos animales se orientan o se reproducen guiándose por la oscuridad natural.", "contaminacion");
q("cielo", "Desde el centro de Montevideo no se ve la Vía Láctea, pero desde el campo sí. ¿Por qué?", ["Por la contaminación lumínica de la ciudad, que aclara el fondo del cielo", "Porque desde Montevideo la Vía Láctea está bajo el horizonte", "Porque en el campo se está más cerca de las estrellas", "Porque la Vía Láctea solo se ve en verano"], "La Vía Láctea es tenue: necesita un cielo bien oscuro.", "contaminacion");
q("cielo", "¿Por qué se ponen telescopios en el espacio, como el Hubble o el James Webb?", ["Para evitar la turbulencia de la atmósfera y observar la luz que ella bloquea (infrarrojo, ultravioleta, rayos X)", "Para estar más cerca de las estrellas", "Porque en la Tierra está prohibido", "Para observar sin necesidad de espejos"], "Unos cientos de kilómetros de altura no acercan a las estrellas, pero sí sacan al telescopio de la atmósfera.", "espaciales");
q("cielo", "El telescopio espacial James Webb observa principalmente en:", ["Infrarrojo", "Rayos X", "Ondas de radio", "Luz visible solamente"], "El infrarrojo atraviesa el polvo y permite ver estrellas en formación y galaxias muy lejanas.", "espaciales");
q("cielo", "¿Por qué muchos grandes observatorios están en el desierto de Atacama, en Chile?", ["Porque es alto, muy seco, oscuro y con cielo despejado casi todo el año", "Porque está más cerca del Sol", "Porque ahí no hay atmósfera", "Porque desde ahí se ve todo el cielo, norte y sur"], "Poca humedad y poca contaminación lumínica dan imágenes más nítidas.", "espaciales");
q("cielo", "¿Qué ha logrado el Observatorio Astronómico Los Molinos, en Montevideo?", ["Descubrir asteroides", "Descubrir un planeta del Sistema Solar", "Fotografiar la cara oculta de la Luna por primera vez", "Lanzar un satélite"], "Es un ejemplo de aporte uruguayo a la astronomía.", "espaciales");
q("cielo", "Antares y Betelgeuse se ven rojizas y Rigel azulada. El color de una estrella indica:", ["La temperatura de su superficie: las rojizas son más frías y las azuladas más calientes", "Su distancia: las rojas están más lejos", "Su edad: las azules son más viejas", "Si tiene planetas"], "Pasa como con un metal al rojo, que está menos caliente que uno al blanco.", "estrellas");
q("cielo", "¿Por qué titilan las estrellas?", ["Porque la turbulencia de la atmósfera desvía su luz", "Porque cambian de brillo cada segundo", "Porque giran sobre sí mismas", "Porque las tapan los satélites"], "Los planetas, que se ven como pequeños discos, titilan menos. En el espacio las estrellas no titilan.", "estrellas");
q("cielo", "¿Por qué no vemos estrellas durante el día?", ["Porque la atmósfera dispersa la luz del Sol y el cielo brillante las tapa", "Porque de día las estrellas están del otro lado de la Tierra", "Porque las estrellas solo brillan de noche", "Porque el Sol las apaga"], "Las estrellas siguen ahí: durante un eclipse total de Sol se ven las más brillantes.", "estrellas");
q("cielo", "¿En qué dirección está el centro de nuestra galaxia?", ["Hacia Sagitario, junto al Escorpión", "Hacia Orión", "Hacia la Cruz del Sur", "Hacia la estrella Polar"], "Por eso la Vía Láctea se ve más brillante y ancha en esa zona, alta en las noches de invierno desde Uruguay.", "profundo");
q("cielo", "El Saco de Carbón, la mancha oscura junto a la Cruz del Sur, es:", ["Una nebulosa oscura de polvo que tapa las estrellas que están detrás", "Un agujero negro", "Una zona sin estrellas", "Una galaxia lejana"], "Es una nube de polvo cercana dentro de la Vía Láctea.", "profundo");
q("cielo", "Omega Centauri, visible a simple vista desde Uruguay, es:", ["Un cúmulo globular: una esfera de cientos de miles de estrellas viejas", "Una estrella doble", "Un planeta", "Una nebulosa de gas"], "Los globulares son viejos y compactos; los cúmulos abiertos, como las Pléyades, son jóvenes y dispersos.", "profundo");
q("cielo", "La Nebulosa de Orión, debajo de las Tres Marías, es:", ["Una región donde se están formando estrellas", "Los restos de una estrella que explotó", "Una galaxia vecina", "Un cometa"], "Es una nube de gas iluminada por estrellas jóvenes que nacieron en ella.", "profundo");
q("cielo", "¿Cuál es el objeto más lejano que se puede ver a simple vista?", ["La galaxia de Andrómeda", "Plutón", "La Nube de Oort", "La estrella Polar"], "Está a unos 2,5 millones de años luz; con cielo muy oscuro se ve como una mancha tenue.", "profundo");

// ───── Movimiento diurno ─────
q("diurno", "A lo largo del año, ¿por qué punto del horizonte sale una misma estrella?", ["Siempre por el mismo punto", "Cada día por un punto distinto, como el Sol", "Siempre exactamente por el este", "Depende de la fase de la Luna"], "La posición de una estrella en la esfera celeste prácticamente no cambia. El Sol sí se mueve sobre la eclíptica y cambia su punto de salida.", "rotacion");
q("diurno", "¿Qué es el ecuador celeste?", ["La proyección del ecuador terrestre sobre la esfera celeste", "El horizonte del observador", "El camino anual del Sol", "El meridiano que pasa por el cenit"], "Divide el cielo en hemisferio norte y sur, igual que el ecuador divide la Tierra.", "esfera");
q("diurno", "El punto de la esfera celeste opuesto al cenit, bajo los pies del observador, se llama:", ["Nadir", "Polo sur celeste", "Punto Libra", "Horizonte"], "Cenit y nadir están sobre la vertical del lugar.", "esfera");

// ───── Orientación ─────
q("orientacion", "¿Por qué las Tres Marías sirven para encontrar el este?", ["Porque están sobre el ecuador celeste: salen por el este exacto y se ponen por el oeste exacto", "Porque siempre están en el cenit", "Porque señalan al polo sur celeste", "Porque son circumpolares"], "Todo astro sobre el ecuador celeste sale y se pone por los puntos este y oeste.", "reloj");
q("orientacion", "Un reloj de sol marca:", ["La hora solar, que en Montevideo difiere de la hora oficial", "La hora oficial de Uruguay", "La hora de Greenwich", "La hora sidérea"], "En Montevideo el reloj de sol va unos 45 minutos atrasado respecto al reloj oficial.", "reloj");
q("orientacion", "Para que un reloj de sol funcione todo el año, su gnomon debe:", ["Ser paralelo al eje de la Tierra, apuntando al polo celeste", "Estar siempre vertical", "Apuntar hacia donde sale el Sol", "Estar acostado sobre el horizonte"], "En Uruguay apunta al polo sur celeste, con una inclinación igual a la latitud.", "reloj");
q("orientacion", "Durante la noche, la Cruz del Sur a veces se ve «acostada» o «de cabeza». ¿Sigue sirviendo para orientarse?", ["Sí: gira alrededor del polo, pero su eje mayor siempre apunta hacia él", "No, solo sirve cuando está parada", "Solo en verano", "No, porque se pone antes de medianoche"], "Desde Montevideo la Cruz es circumpolar: está toda la noche sobre el horizonte, girando alrededor del polo.", "reloj");
q("orientacion", "Desde Montevideo, la Cruz del Sur:", ["Es circumpolar: nunca se pone", "Solo se ve en verano", "Sale por el este y se pone por el oeste", "Nunca se ve"], "Está muy cerca del polo sur celeste, que en Montevideo está unos 35° sobre el horizonte.", "reloj");

// ───── UA y año luz ─────
q("distancias", "¿Qué unidad conviene para expresar la distancia entre la Tierra y Marte?", ["La unidad astronómica", "El año luz", "El metro", "El pársec"], "Para el Sistema Solar, la UA da números manejables; el año luz sería una fracción diminuta.", "escala");
q("distancias", "¿Qué es más grande?", ["Un año luz", "Una unidad astronómica", "Son iguales", "Depende de la época del año"], "Un año luz equivale a unas 63 000 UA.", "escala");
q("distancias", "Si el Sol se apagara de repente, ¿cuándo lo notaríamos en la Tierra?", ["Unos 8 minutos después", "Al instante", "Un año después", "Un día después"], "Su última luz todavía estaría viajando hacia nosotros.", "escala");
q("distancias", "Cuando miramos la galaxia de Andrómeda, la vemos:", ["Como era hace unos 2,5 millones de años", "Como es ahora", "Como será en el futuro", "Como era hace 8 minutos"], "Su luz tarda unos 2,5 millones de años en llegar: mirar lejos es mirar al pasado.", "escala");
q("distancias", "¿Hasta dónde se extiende aproximadamente la nube de Oort, el borde del Sistema Solar?", ["Hasta alrededor de un año luz del Sol", "Hasta la órbita de Neptuno", "Hasta 1 UA", "Hasta la estrella más cercana"], "Neptuno está a solo 30 UA; la nube de Oort está miles de veces más lejos.", "escala");
q("distancias", "¿A qué velocidad viaja la luz aproximadamente?", ["300 000 km/s", "300 km/s", "300 000 km/h", "Es instantánea"], "Es la máxima velocidad posible: ningún objeto viaja más rápido.", "al");
q("distancias", "¿Para qué distancias es adecuado el kilómetro?", ["Para distancias dentro de la Tierra o hasta la Luna", "Para distancias entre estrellas", "Para distancias entre galaxias", "Para la distancia al Sol en el día a día"], "Para los planetas se usa la UA y para las estrellas, el año luz.", "escala");

// ───── Estaciones ─────
q("estaciones", "Según la primera ley de Kepler, la órbita de la Tierra es:", ["Una elipse con el Sol en uno de sus focos", "Un círculo perfecto con el Sol en el centro", "Una elipse con el Sol en el centro", "Una espiral que se aleja del Sol"], "Igual es casi circular: la distancia al Sol varía solo un 3 %.", "orbita");
q("estaciones", "¿Cuál es la estación más corta en el hemisferio sur?", ["El verano", "El invierno", "La primavera", "Todas duran exactamente lo mismo"], "En enero la Tierra está en el perihelio y, por la 2.ª ley de Kepler, se mueve más rápido.", "orbita");
q("estaciones", "¿Por qué el invierno austral dura algunos días más que el verano austral?", ["Porque en junio y julio la Tierra está lejos del Sol y se mueve más despacio en su órbita", "Porque el eje de la Tierra se inclina más en invierno", "Porque en invierno los días son más cortos", "Porque el Sol se mueve más lento en invierno"], "La 2.ª ley de Kepler: más lejos del Sol, menor velocidad orbital.", "orbita");
q("estaciones", "La distancia Tierra–Sol varía durante el año alrededor de:", ["Un 3 %, muy poco para causar las estaciones", "Un 50 %", "Nada, es constante", "Un 300 %"], "Por eso la órbita es casi circular y lo que causa las estaciones es la inclinación del eje.", "orbita");
q("estaciones", "En el ecuador terrestre, ¿cuánto dura el día a lo largo del año?", ["Unas 12 horas todo el año", "24 horas en verano", "Varía entre 6 y 18 horas", "Solo hay día en los equinoccios"], "En el ecuador cada astro pasa la mitad de su recorrido diario sobre el horizonte.", "dia");
q("estaciones", "El «Sol de medianoche» (días en que el Sol no se pone) ocurre:", ["Dentro de los círculos polares, en su verano", "En el ecuador, en los equinoccios", "En Uruguay, en el solsticio de verano", "En todo el planeta una vez al año"], "En invierno, dentro de esos círculos, hay días en que el Sol no sale.", "dia");
q("estaciones", "Si sacas una foto del amanecer desde el mismo lugar una vez por mes durante un año, verás que el punto de salida del Sol:", ["Se desplaza entre el noreste (junio) y el sudeste (diciembre)", "Es siempre el mismo", "Recorre todo el horizonte", "Se desplaza entre el norte y el sur exactos"], "Solo en los equinoccios sale por el este exacto.", "dia");
q("estaciones", "«Solsticio» significa «Sol quieto». ¿A qué se refiere?", ["A que el punto de salida del Sol deja de desplazarse por el horizonte y empieza a volver", "A que el Sol no se mueve en el cielo durante ese día", "A que ese día no hay viento solar", "A que el Sol no sale ese día"], "Es el extremo de su recorrido anual hacia el norte o hacia el sur.", "dia");
q("estaciones", "En el hemisferio sur, el equinoccio de marzo marca el comienzo:", ["Del otoño", "De la primavera", "Del verano", "Del invierno"], "El de setiembre marca el comienzo de la primavera austral.", "dia");
q("estaciones", "¿En qué época del año son más largas las sombras al mediodía en Uruguay?", ["En invierno", "En verano", "En los equinoccios", "Son iguales todo el año"], "En invierno el Sol culmina más bajo, así que las sombras son más largas.", "dia");
q("estaciones", "En verano los días son más largos que en invierno porque:", ["El Sol recorre en el cielo un arco más largo sobre el horizonte", "La Tierra gira más despacio", "La Tierra está más cerca del Sol", "La Luna refleja más luz"], "La inclinación del eje cambia qué parte del recorrido diario del Sol queda sobre el horizonte.", "dia");

// ───── Fases de la Luna ─────
q("luna", "¿Hacia qué dirección se desplaza la Luna entre las estrellas, día a día?", ["Hacia el este, unos 13° por día", "Hacia el oeste, unos 13° por día", "Hacia el este, 1° por día", "No se desplaza"], "Por eso sale cada día unos 50 minutos más tarde.", "movimiento");
q("luna", "El lado iluminado de la Luna, en cualquier fase, apunta siempre:", ["Hacia el Sol", "Hacia la Tierra", "Hacia el este", "Hacia el polo sur celeste"], "Es la mitad que mira al Sol; vemos más o menos de ella según dónde esté la Luna.", "movimiento");
q("luna", "Un mismo día, una persona en Uruguay y otra en Japón ven la Luna. ¿Qué fase ven?", ["La misma fase, aunque orientada distinto", "Fases opuestas", "La de Japón va una semana adelantada", "Depende del huso horario"], "La fase depende de la posición Sol–Tierra–Luna, que es la misma para todos.", "movimiento");
q("luna", "En una Luna creciente muy fina se alcanza a ver, tenue, el resto del disco. Esa «luz cenicienta» es:", ["Luz del Sol reflejada por la Tierra que ilumina la parte oscura de la Luna", "Luz propia de la Luna", "La sombra de la Tierra", "Luz de las estrellas"], "Leonardo da Vinci ya la explicaba así.", "movimiento");
q("luna", "Si desde la Tierra vemos Luna llena, un astronauta en la Luna vería la Tierra:", ["En fase «nueva», casi sin iluminar", "Llena", "En cuarto creciente", "No la vería"], "Las fases de la Tierra vistas desde la Luna son opuestas a las de la Luna vistas desde la Tierra.", "movimiento");
q("luna", "Entre Luna nueva y Luna llena pasan aproximadamente:", ["15 días", "7 días", "29,5 días", "3 días"], "Es la mitad del ciclo de 29,5 días.", "ciclo");
q("luna", "Al atardecer ves una Luna creciente fina, baja en el cielo. ¿Hacia dónde está?", ["Hacia el oeste, cerca de donde se puso el Sol", "Hacia el este", "Hacia el sur, cerca de la Cruz", "En el cenit"], "La creciente está poco al este del Sol, así que se pone poco después que él.", "horarios");
q("luna", "Se llama «cuarto creciente» aunque vemos iluminada la mitad del disco porque:", ["La Luna recorrió un cuarto de su órbita desde la Luna nueva", "Vemos un cuarto de la superficie de la Luna", "Dura un cuarto de mes", "La luz llega a un cuarto de su intensidad"], "El nombre se refiere al recorrido orbital, no a la forma.", "ciclo");
q("luna", "El punto de la órbita de la Luna más cercano a la Tierra se llama:", ["Perigeo", "Apogeo", "Perihelio", "Nodo"], "El más lejano es el apogeo. Perihelio se usa para órbitas alrededor del Sol.", "movimiento");

// ───── Eclipses ─────
q("eclipses", "En un mapa de un eclipse total de Sol, la franja angosta dibujada sobre la Tierra indica:", ["La zona desde donde el eclipse se ve total", "La zona desde donde no se ve el eclipse", "La órbita de la Luna", "Los lugares donde será de noche"], "A los costados de la franja, en una zona mucho más amplia, el eclipse se ve parcial.", "visibilidad");
q("eclipses", "Durante un eclipse de Sol, la sombra de la Luna recorre la Tierra:", ["De oeste a este", "De este a oeste", "De norte a sur", "No se mueve"], "La Luna avanza en su órbita hacia el este más rápido de lo que gira la superficie terrestre.", "visibilidad");
q("eclipses", "En un lugar fijo de la Tierra, un eclipse total de Sol se repite en promedio cada:", ["Unos 375 años", "Un año", "Unos 18 años", "Unos 10 años"], "Por eso mucha gente viaja para ver uno. Hay eclipses totales cada año o dos, pero en franjas distintas.", "visibilidad");
q("eclipses", "¿Qué pasa durante la totalidad de un eclipse de Sol?", ["Baja la temperatura, se ven las estrellas brillantes y los animales actúan como al anochecer", "Se hace de noche en todo el planeta", "La Luna se pone roja", "Aumenta la temperatura"], "Son unos minutos de crepúsculo en pleno día.", "visibilidad");
q("eclipses", "Un eclipse total de Luna empieza a las 23:00 en Montevideo. Para alguien en otro país donde también es de noche, el eclipse:", ["Empieza en el mismo instante, aunque a otra hora local", "Empieza horas después", "No se ve", "Se ve solo parcial"], "Lo que oscurece la Luna es la sombra de la Tierra, la misma para todos los que la ven.", "visibilidad");
q("eclipses", "En un eclipse penumbral de Luna:", ["La Luna solo pasa por la penumbra de la Tierra y apenas se oscurece", "La Luna se vuelve roja", "El Sol se oscurece", "La Luna desaparece completamente"], "Muchas veces pasa desapercibido sin prestar atención.", "visibilidad");
q("eclipses", "¿Qué observó Aristóteles en los eclipses de Luna para afirmar que la Tierra es esférica?", ["Que la sombra de la Tierra sobre la Luna es siempre curva", "Que la Luna se ve roja", "Que los eclipses ocurren en Luna llena", "Que la Luna desaparece por completo"], "Solo una esfera proyecta siempre una sombra circular, desde cualquier ángulo.", "cultural");
q("eclipses", "¿Cómo explicaban muchas culturas antiguas los eclipses de Sol?", ["Como un animal o un monstruo que devoraba al Sol", "Como la sombra de la Luna", "Como una tormenta solar", "Como un apagón de la Tierra"], "Eran vividos como presagios; hoy se predicen con siglos de anticipación.", "cultural");
q("eclipses", "¿Qué se confirmó en el eclipse total de Sol de 1919?", ["Que la luz de las estrellas se desvía al pasar cerca del Sol, como predijo la relatividad de Einstein", "Que la Tierra es redonda", "Que la Luna tiene atmósfera", "Que el Sol gira"], "Durante la totalidad se pudieron fotografiar estrellas junto al borde del Sol.", "cultural");
q("eclipses", "Según la tradición griega, ¿quién predijo un eclipse de Sol en el 585 a. C.?", ["Tales de Mileto", "Galileo Galilei", "Isaac Newton", "Nicolás Copérnico"], "Las predicciones de eclipses se basaban en ciclos observados durante siglos, como el Saros.", "cultural");

// ───── Calendario ─────
q("calendario", "¿Por qué setiembre se llama así si es el noveno mes?", ["Porque el año romano empezaba en marzo y setiembre era el séptimo mes", "Porque tiene siete semanas", "Por un emperador llamado Septimio", "Porque tiene 7 días festivos"], "Octubre, noviembre y diciembre también conservan los números 8, 9 y 10.", "historia");
q("calendario", "Los meses de julio y agosto deben su nombre a:", ["Julio César y el emperador Augusto", "Dos planetas", "Dos dioses griegos", "Dos constelaciones"], "Julio César también impuso el calendario juliano.", "historia");
q("calendario", "En el antiguo Egipto, la salida de Sirio justo antes del amanecer anunciaba:", ["La crecida del Nilo", "El invierno", "Un eclipse", "El fin del año lunar"], "Los egipcios usaban un año de 365 días.", "historia");
q("calendario", "El mediodía solar no cae todos los días a la misma hora del reloj. La diferencia se llama:", ["Ecuación del tiempo, y llega a unos 16 minutos", "Precesión, y llega a 1 hora", "Huso horario, y es de 15 minutos", "Año bisiesto, y es de 6 horas"], "Se debe a la órbita elíptica de la Tierra y a la inclinación de su eje.", "historia");
q("calendario", "Al cruzar la línea internacional de cambio de fecha:", ["Se suma o se resta un día", "Se cambia de estación", "Se adelanta una hora", "No pasa nada"], "Está cerca del meridiano 180°, en el océano Pacífico.", "historia");
q("calendario", "¿Qué es la precesión del eje terrestre?", ["Un giro lento del eje de la Tierra, como un trompo, que tarda unos 26 000 años", "El cambio de estaciones", "La rotación diaria de la Tierra", "Un temblor del eje cada año bisiesto"], "Hace que los equinoccios se desplacen lentamente entre las estrellas.", "precesion");
q("calendario", "¿Por qué nuestro calendario sigue el año trópico y no el año sidéreo?", ["Porque lo importante es que las estaciones caigan siempre en las mismas fechas", "Porque el sidéreo es más largo que un siglo", "Porque el trópico depende de la Luna", "Por tradición, sin ninguna razón astronómica"], "El año trópico mide el ciclo de las estaciones; el sidéreo, la vuelta respecto a las estrellas.", "precesion");
q("calendario", "Por la precesión, dentro de miles de años:", ["La estrella que marque el polo norte celeste será otra", "Cambiará la duración del día", "La Tierra tendrá más estaciones", "La Luna dejará de tener fases"], "Hoy es Polaris; dentro de unos 12 000 años estará cerca de Vega.", "precesion");

// ───── Sistema Solar ─────
q("sistema", "¿Cuáles son los planetas interiores, es decir, los que orbitan más cerca del Sol que la Tierra?", ["Mercurio y Venus", "Mercurio, Venus, Tierra y Marte", "Marte y Júpiter", "Solo Mercurio"], "Por eso Mercurio y Venus nunca se ven a medianoche.", "comparada");
q("sistema", "¿Qué planeta tiene menor densidad, incluso menor que la del agua?", ["Saturno", "Júpiter", "Mercurio", "La Tierra"], "La Tierra, en cambio, es el planeta más denso.", "comparada");
q("sistema", "¿Qué planeta rota más rápido sobre sí mismo, con un día de unas 10 horas?", ["Júpiter", "Mercurio", "Venus", "La Tierra"], "A pesar de ser el más grande, es el que gira más rápido.", "comparada");
q("sistema", "¿En qué planeta un día dura más que un año?", ["Venus", "Mercurio", "Marte", "Neptuno"], "Venus rota muy despacio y al revés que la mayoría de los planetas.", "comparada");
q("sistema", "¿Qué planetas no tienen ninguna luna?", ["Mercurio y Venus", "Marte y Venus", "Mercurio y Marte", "Urano y Neptuno"], "Marte tiene dos pequeñas, Fobos y Deimos.", "comparada");
q("sistema", "Los planetas rocosos tienen en su interior:", ["Un núcleo metálico, un manto y una corteza", "Gas en todo su interior", "Hielo en todo su interior", "Un núcleo de hidrógeno líquido y nada más"], "Los gigantes, en cambio, no tienen superficie sólida.", "comparada");
q("sistema", "¿Por qué Mercurio y la Luna están llenos de cráteres?", ["Porque casi no tienen atmósfera ni actividad geológica que borre los impactos", "Porque reciben más meteoritos que la Tierra", "Porque son volcanes apagados", "Porque están hechos de hielo"], "En la Tierra, la erosión y la tectónica borran la mayoría de los cráteres.", "geologia");
q("sistema", "¿Dónde está el Olimpo (Olympus Mons), el volcán más grande conocido del Sistema Solar?", ["En Marte", "En la Tierra", "En Venus", "En Ío"], "Mide unos 22 km de altura, más del doble que el Everest.", "geologia");
q("sistema", "¿Por qué Mercurio tiene diferencias de temperatura tan grandes entre el día y la noche?", ["Porque casi no tiene atmósfera que retenga el calor", "Porque su órbita es la más larga", "Porque está hecho de hielo", "Porque rota muy rápido"], "Pasa de unos 430 °C de día a −180 °C de noche.", "geologia");
q("sistema", "La atmósfera de Marte es:", ["Muy tenue y formada sobre todo por CO₂", "Densa y formada por nitrógeno y oxígeno", "Inexistente", "Densa y formada por metano"], "Por eso Marte es frío y el agua líquida no puede mantenerse en su superficie.", "geologia");
q("sistema", "Los casquetes polares de Marte están formados por:", ["Hielo de agua y de dióxido de carbono", "Sal", "Nieve de metano", "Lava solidificada"], "Crecen y se achican con las estaciones marcianas.", "geologia");
q("sistema", "¿Qué evidencias hay de que en Marte hubo agua líquida?", ["Cauces secos y minerales que se forman en agua, observados por sondas y rovers", "Que hoy llueve en Marte", "Que tiene océanos visibles con telescopio", "Ninguna, nunca la hubo"], "Hoy el agua de Marte está congelada en el suelo y en los casquetes.", "geologia");
q("sistema", "¿Qué planeta es el único conocido con tectónica de placas activa?", ["La Tierra", "Venus", "Marte", "Mercurio"], "La tectónica recicla la corteza y forma montañas, volcanes y terremotos.", "geologia");
q("sistema", "La Gran Mancha Roja de Júpiter es:", ["Una tormenta más grande que la Tierra, observada desde hace más de 150 años", "Un volcán", "Un cráter de impacto", "La sombra de una de sus lunas"], "Es un enorme anticiclón en la atmósfera de Júpiter.", "geologia");
q("sistema", "¿Qué planeta tiene los vientos más rápidos del Sistema Solar?", ["Neptuno", "La Tierra", "Mercurio", "Marte"], "Superan los 2000 km/h.", "geologia");
q("sistema", "La atmósfera de Venus es:", ["Muy densa, de CO₂, con nubes de ácido sulfúrico", "Muy tenue, de CO₂", "De nitrógeno y oxígeno, como la terrestre", "Inexistente"], "Su enorme efecto invernadero hace de Venus el planeta más caliente.", "geologia");
q("sistema", "¿Cuál es la luna más grande del Sistema Solar, incluso mayor que Mercurio?", ["Ganímedes", "Titán", "La Luna", "Ío"], "Es una de las cuatro lunas galileanas de Júpiter.", "lunas");
q("sistema", "¿Qué luna tiene una atmósfera densa y lagos de metano?", ["Titán, de Saturno", "Europa, de Júpiter", "Fobos, de Marte", "La Luna"], "Es la única luna con una atmósfera densa, sobre todo de nitrógeno.", "lunas");
q("sistema", "Europa (Júpiter) y Encélado (Saturno) interesan en la búsqueda de vida porque:", ["Tienen océanos de agua líquida bajo su superficie helada", "Tienen atmósferas como la terrestre", "Son los cuerpos más calientes del Sistema Solar", "Tienen plantas visibles"], "Encélado incluso lanza chorros de agua al espacio.", "lunas");
q("sistema", "Ceres es:", ["Un planeta enano, el mayor objeto del cinturón de asteroides", "Una luna de Marte", "Un cometa", "Un planeta gigante"], "Es el único planeta enano en la zona interior del Sistema Solar.", "lunas");
q("sistema", "¿Cuál de estos es un planeta enano más allá de Neptuno, de tamaño parecido a Plutón?", ["Eris", "Ceres", "Titán", "Fobos"], "Su descubrimiento impulsó la discusión que terminó con la nueva definición de planeta en 2006.", "lunas");
q("sistema", "Según la UAI, los asteroides y los cometas son:", ["Cuerpos menores del Sistema Solar", "Planetas enanos", "Satélites", "Estrellas fallidas"], "Cuerpo menor es todo lo que no es planeta, planeta enano ni satélite.", "lunas");
q("sistema", "Los cometas de período largo, que tardan miles de años en volver, provienen de:", ["La nube de Oort", "El cinturón principal de asteroides", "Los anillos de Saturno", "El Sol"], "Los de período corto suelen venir del cinturón de Kuiper.", "cometas");
q("sistema", "¿Cada cuánto vuelve el cometa Halley?", ["Unos 76 años", "Cada año", "Unos 3 años", "Unos 1000 años"], "Su próximo paso será en 2061.", "cometas");
q("sistema", "Una lluvia de meteoros, como las Perseidas, se produce cuando:", ["La Tierra cruza los restos de polvo que dejó un cometa en su órbita", "Un asteroide se rompe en la atmósfera", "Caen estrellas", "La Luna pasa cerca de la Tierra"], "Por eso se repiten cada año en las mismas fechas.", "cometas");
q("sistema", "En una lluvia de meteoros, los meteoros parecen salir de un mismo punto del cielo, llamado:", ["Radiante", "Cenit", "Nodo", "Perihelio"], "Es un efecto de perspectiva; la lluvia toma el nombre de la constelación donde está el radiante.", "cometas");
q("sistema", "¿Cuál es el objeto construido por humanos que está más lejos de la Tierra?", ["La sonda Voyager 1", "El telescopio James Webb", "La Estación Espacial Internacional", "El rover Perseverance"], "Lanzada en 1977, ya viaja por el espacio interestelar.", "exploracion");
q("sistema", "¿Qué misión mostró por primera vez de cerca la superficie de Plutón, en 2015?", ["New Horizons", "Voyager 2", "Cassini", "Juno"], "Reveló montañas de hielo y una gran llanura en forma de corazón.", "exploracion");
q("sistema", "El rover Perseverance, que llegó a Marte en 2021, tiene como objetivo:", ["Buscar señales de vida pasada y juntar muestras de rocas", "Instalar una base humana", "Estudiar los anillos de Marte", "Medir la temperatura del Sol"], "Las muestras podrían traerse a la Tierra en una misión futura.", "exploracion");
q("sistema", "¿Qué sonda estudió Saturno y sus lunas hasta 2017?", ["Cassini", "New Horizons", "Perseverance", "Parker Solar Probe"], "Terminó su misión zambulléndose en la atmósfera de Saturno.", "exploracion");
q("sistema", "¿Qué hace que la Tierra sea habitable?", ["Tener agua líquida, una atmósfera que regula la temperatura y un campo magnético que la protege", "Ser el planeta más grande", "Estar en el centro del Sistema Solar", "No tener estaciones"], "Venus y Marte muestran lo que pasa cuando alguna de esas condiciones falla.", "habitable");
q("sistema", "La zona de habitabilidad alrededor de una estrella es:", ["La región donde un planeta podría tener agua líquida en su superficie", "La zona donde hay oxígeno", "La región sin asteroides", "La zona iluminada del planeta"], "La Tierra está dentro de la zona de habitabilidad del Sol; Venus está demasiado cerca y Marte en el borde exterior.", "habitable");
q("sistema", "¿Para qué sirve el campo magnético de la Tierra?", ["Para protegerla del viento solar", "Para mantener la Luna en órbita", "Para producir las estaciones", "Para generar la gravedad"], "Las auroras se producen cuando partículas del viento solar entran cerca de los polos.", "habitable");
q("sistema", "¿Cómo se sabe que el Sistema Solar tiene unos 4600 millones de años?", ["Datando con radiactividad los meteoritos más antiguos", "Contando los cráteres de la Luna uno por uno", "Midiendo la temperatura del Sol", "Por los textos de los astrónomos antiguos"], "Los meteoritos más antiguos se formaron junto con el Sistema Solar y casi no cambiaron desde entonces.", "formacion");
q("sistema", "¿Cuál es la explicación más aceptada sobre el origen de la Luna?", ["Un gran impacto de un cuerpo del tamaño de Marte contra la Tierra joven", "La Tierra la capturó cuando pasaba cerca", "Se separó de la Tierra por su rotación rápida", "Se formó junto al Sol"], "Los restos del choque formaron un anillo que se juntó y formó la Luna.", "formacion");
q("sistema", "Los planetas se formaron a partir de:", ["Pequeños cuerpos (planetesimales) que chocaron y se fueron juntando en el disco alrededor del Sol joven", "Pedazos que se desprendieron del Sol", "Estrellas que se apagaron", "La explosión de una supernova dentro del Sistema Solar"], "Ese proceso se llama acreción.", "formacion");
q("sistema", "¿Qué le pasará al Sol dentro de unos 5000 millones de años?", ["Se convertirá en gigante roja y luego en enana blanca", "Explotará como supernova", "Se convertirá en agujero negro", "Se apagará de golpe"], "No tiene masa suficiente para explotar como supernova.", "formacion");
